window.HARDTRP.receive("1508",[[1509,"2026-05-19T18:06:59",9,"Начало темы.\n\n@Psinablohastay Дм этой темы.",1508,null],[1511,"2026-05-19T19:01:11",56,"//Предлагаю писать по очереди, чтоб я смог ответить каждому на его пост, а то я пишу не очень быстро, вы уж простите, надеюсь никто не против?",1508,null],[1512,"2026-05-19T19:02:13",56,"Список участников:\n1. Леда ( Hard  )\n2. Урхак ( @l_f_z_t )\n3. Фембойчик Астольфо( @Az095as0 )",1508,null],[1513,"2026-05-19T19:02:25",56,"Вы готовы дети?",1508,null],[1514,"2026-05-19T19:02:41",44,"// да капитан мы готовы!",1513,null],[1515,"2026-05-19T19:03:25",56,"//жду остальных",1508,null],[1516,"2026-05-19T19:14:22",9,"//Тут",1508,null],[1517,"2026-05-19T19:15:56",56,"Ждëм @l_f_z_t",1508,null],[1518,"2026-05-19T19:19:42",56,"//я ща шафл танцевать начну, где наша чувырла",1508,null],[1519,"2026-05-19T19:26:19",56,"//ну, начинать на 2-х людей такое себе",1508,null],[1520,"2026-05-19T19:26:28",56,"//Что думаете?",1508,null],[1521,"2026-05-19T19:28:35",9,"//Я подожду",1508,null],[1522,"2026-05-19T19:28:41",44,"// мне честно все равно , просто мне нужно доделать дела . Так что я не против подождать",1520,null],[1530,"2026-05-20T01:18:14",44,"// я решил заранее кинуть 2д20 от классового умение волшебника прорицание",1508,null],[1531,"2026-05-20T01:18:21",44,"/r 2d20",1508,null],[1534,"2026-05-20T09:23:47",56,"Уфффф",1532,null],[1535,"2026-05-20T09:23:49",56,"Жоско",1508,null],[1536,"2026-05-20T12:50:34",44,"@Psinablohastay , я хочу задать пору вопросов \n1 мой классовое умение прорицание будет работать по строгим правил или я могу значил узнать результат и могу решить использовать умение класса или нет ?\n\n2 если он сегодня не вернётся до 6 часов вечера, то можно я пока что в других приключение поиграю ?",1508,null],[1537,"2026-05-20T13:07:52",56,"Классовое умение можно делать и не таким строгим",1536,null],[1538,"2026-05-20T13:08:50",44,"Ну просто некоторые мастера забивает правила использования  этого умения. Так что я просто уточняю",1537,null],[1542,"2026-05-20T19:04:26",31,"Господа, играть то будем? Я просто с большой долей вероятности через час уже усну)",1508,null],[1543,"2026-05-20T19:05:26",9,"//Тебя Ы собирается вести соло вродь. Тема \"Семейный ужин\"",1542,null],[1544,"2026-05-20T19:06:05",31,"Ок, просто меня сюда выбросило по ссылке",1508,null],[1546,"2026-05-20T19:06:52",44,"// а да , мне можно пока что в другие квесты поучаствовать пока он пропадает ?",1543,null],[1547,"2026-05-20T19:07:30",9,"//Этот квест так и не начался так что да)",1546,null],[1551,"2026-05-20T19:08:25",56,"//Агась, обидно конечно, но что поделать",1547,null],[1552,"2026-05-20T19:08:25",44,"// много мы тут насрал. ,  нужно потом тут почисти до мох просков 2д20 ,",1508,null],[1553,"2026-05-20T19:08:55",9,"//Можно наоборот, вместо Лей взять других и начать",1551,null],[1561,"2026-05-20T19:26:27",56,"Ну, мне как-то неудобно, хз",1553,null],[1562,"2026-05-20T19:27:48",44,"Я согласен , просто он может вернутся в любой момент, но по-сути он сам виноват что пропал без предупреждени",1561,null],[1564,"2026-05-20T19:29:04",56,"Ладно, что делаем в итоге?",1562,null],[1565,"2026-05-20T19:31:56",44,"Хз, а вообще он говорил, что свободен в воскресенье. Так что подождем до воскресенья. Если он не придет даже в воскресенье, то можно начать игру без него или найти ему замену",1564,null],[2905,"2026-05-22T16:43:03",56,"//кстати, а мы когда собираемся, ребят?",1508,null],[2906,"2026-05-22T16:44:34",44,"// это хз , ну мой персонаж уже в  другом приключение , но если хотите играть  то може начинать без меня",2905,null],[2912,"2026-05-22T16:54:13",9,"//Леда тоже на другом, ищи новых игроков или нас подожди)",1508,null],[6718,"2026-05-26T17:39:44",56,"Хочу потихоньку начать.Вы как, готовы? \n@landihus \n@Pro551o \n@Ashenchampion \n@elsio28 \n@Az095as0",1508,null],[6719,"2026-05-26T17:39:57",11,"Я тут",1508,null],[6723,"2026-05-26T17:42:02",11,"жесть крутой малой",6720,null],[6726,"2026-05-26T17:42:42",56,"Это я кста",6723,null],[6727,"2026-05-26T17:42:45",56,"Сам снимал",1508,null],[6728,"2026-05-26T17:58:46",61,"@Psinablohastay elsio добавьте сюда",1508,null],[6729,"2026-05-26T18:01:05",44,"// я тут пупсики",6718,null],[6731,"2026-05-26T18:04:31",56,"Его нет в группе?",6728,null],[6732,"2026-05-26T18:04:40",56,"Все здесь?",1508,null],[6734,"2026-05-26T18:04:59",61,"нет",6731,null],[6736,"2026-05-26T18:07:16",56,"А @Pro551o  где?",1508,null],[6737,"2026-05-26T18:07:52",56,"@elsio28",1508,null],[6738,"2026-05-26T18:07:58",56,"Мы тута",1508,null],[6739,"2026-05-26T18:08:24",5,"привет",1508,null],[6740,"2026-05-26T18:09:04",56,"Дароу",1508,null],[6741,"2026-05-26T18:09:07",56,"Ждём про",1508,null],[6742,"2026-05-26T18:47:13",56,"@Pro551o",1508,null],[6744,"2026-05-26T18:54:08",56,"Я щас по пяткам стрелять начну",1508,null],[6748,"2026-05-26T19:43:47",23,"...",1508,null],[6750,"2026-05-26T19:49:17",56,"ЕБААААТТ",1508,null],[6751,"2026-05-26T19:49:22",56,"ВСЕ ПРИШЛИ?",1508,null],[6753,"2026-05-26T19:50:03",44,"Я да ,",6751,null],[6754,"2026-05-26T19:50:09",56,"//потом Прайм на Менди доапаю",1508,null],[6755,"2026-05-26T19:50:13",56,"//начинаем",1508,null],[6756,"2026-05-26T19:50:33",56,"//позязя,пишите по очереди, а то пишу я очень медленно)",1508,null],[6757,"2026-05-26T19:50:52",23,"напомните что где Почему мы",1508,null],[6758,"2026-05-26T19:51:05",44,"// конечно мы будем писать по очереди ( нет )",6756,null],[6759,"2026-05-26T19:51:14",23,"можно меня просто выпнуть у меня один персонаж то там то тут меня разорвут",6756,null],[6760,"2026-05-26T19:51:22",23,"а хотя стоп У меня есть один свободный персонаж....",1508,null],[6761,"2026-05-26T19:51:29",23,"НАКОНЕЦ-ТО СВОБОДНЫЙ",1508,null],[6762,"2026-05-26T19:51:31",56,"Вы откликнулись на просьбу старика о помощи, у него потерялся друг, вот он его и ищет",1508,null],[6763,"2026-05-26T19:51:43",56,"//таааак",6759,null],[6764,"2026-05-26T19:51:43",23,"сейчас один бард заменит другого",6762,null],[6765,"2026-05-26T19:51:52",56,"Ты тогда идёшь или нет?",1508,null],[6766,"2026-05-26T19:52:00",23,"разрешишь мне на кобальде играть?",6765,null],[6767,"2026-05-26T19:52:03",23,"Я забыл как его зовут",1508,null],[6768,"2026-05-26T19:52:08",23,"шя",1508,null],[6769,"2026-05-26T19:52:17",56,"//А-а-а, ну слушай",6766,null],[6770,"2026-05-26T19:52:31",56,"//так даже лучше, вы в пещеру к дракону идёте)",1508,null],[6771,"2026-05-26T19:53:17",23,"https://t.me/c/3239766844/151/157",1508,null],[6772,"2026-05-26T19:53:22",23,"во",1508,null],[6773,"2026-05-26T19:53:30",23,"эхххх",6770,null],[6774,"2026-05-26T19:53:33",23,"от одного к другому",1508,null],[6775,"2026-05-26T19:53:36",23,"третий уже",1508,null],[6776,"2026-05-26T19:53:48",23,"эхххххххххххххх бедный кобальт",1508,null],[6777,"2026-05-26T19:53:56",23,"или кобальд",1508,null],[6778,"2026-05-26T19:54:10",56,"//к мёртвому",6774,null],[6779,"2026-05-26T19:54:22",23,"это когда-нибудь останавливало Барда?",6778,null],[6781,"2026-05-26T19:56:57",56,"@elsio28 @landihus @Ashenchampion  вы как?",1508,null],[6782,"2026-05-26T19:57:08",5,"мы тут",1508,null],[6783,"2026-05-26T19:57:13",5,"только не понимаем что к чему",1508,null],[6784,"2026-05-26T19:57:30",23,"так как всегда предлагаю в самом начале покидать свои арты",1508,null],[6785,"2026-05-26T19:57:44",23,"~",1508,null],[6786,"2026-05-26T19:58:16",23,"для удобства просто",1508,null],[6787,"2026-05-26T19:58:36",11,"Мхм, мы не рисовали ничего",1508,null],[6789,"2026-05-26T19:58:58",56,"Окей, кидайте, дайте знак, как готовы будете?",1508,null],[6790,"2026-05-26T19:59:08",11,"Да мы уже два часа как готовы",1508,null],[6791,"2026-05-26T20:00:24",23,"~Ну я ничего не рисовал тоже",6787,null],[6793,"2026-05-26T20:00:52",23,"кобальт",1508,null],[6794,"2026-05-26T20:02:15",56,"Хорошо, начинаем",1508,null],[6796,"2026-05-26T20:02:38",23,"а кстати меня нету Зачем меня дарили",1512,null],[6797,"2026-05-26T20:02:39",56,"Или нет?",1508,null],[6798,"2026-05-26T20:02:48",44,"Наконец-то я ждал это четы.., нет пять тысяч лет",6794,null],[6799,"2026-05-26T20:03:24",56,"Ранний час. Город ещё дремлет, укутанный сизой предрассветной дымкой. Первые лучи солнца робко золотят черепицу крыш, и знакомые улочки. У северных ворот почти ни души  лишь редкий стражник видит десятый сон, да и где-то вдалеке перекликаются петухи\n\nКаждый из вас пришёл сюда, ведомый одним и тем же порывом. Объявление, что принесла в клюве сова, задело какую-то струну внутри. У кого-то жажду наживы, у кого-то любопытство, а у кого-то и нечто более глубокое, о чём не принято говорить вслух. И вот, у массивных дубовых створок, вы видите его.\n\nСедой старик лет шестидесяти, не меньше. Сначала вы замечаете тёмную, как смоль, повязку, закрывающую глаза, а затем и церковное одеяние. Оно на удивление скромное простая тёмная ряса, потёртая на локтях, без богатых вышивок и драгоценных украшений,что странно для служителей его сана. Лишь на груди тускло поблёскивает скромный священный символ на простом шнурке, который он держит сейчас в сложенных ладонях.\n\nОн обращён лицом к восходящему солнцу и истово молится. Губы его едва шевелятся, и шёпот, доносящийся до вас, разобрать почти невозможно. Вокруг него широкими плавными кругами летает сова. Та самая. Вы узнаёте её сразу: серая неясыть с пронзительными янтарными глазами.\n\nВ какой-то момент старик замирает. Он чувствует ваше присутствие раньше, чем вы успеваете подать голос, то ли по звуку шагов, то ли по изменению самого воздуха вокруг. Медленно, он убирает символ за пазуху и поворачивает голову в вашу сторону.\nВас накрывает запах. От старика пахнет полевыми цветами, но не теми, что выращивают в ухоженных садах. Это запах дикого луга, ромашек и клевера, запах свежей травы и утренней росы на колосьях. Он обволакивает вас тёплой волной.\n\nВы всматриваетесь в его лицо. И замечаете печаль, не мимолётная грусть, не старческая усталость, а глубокая скорбь по чему-то безвозвратно ушедшему. Если вы читали объявление, то понимаете — вот оно, лицо человека, который полвека ждёт угасшего пламени.\n\nСова тем временем заканчивает свой облёт и аккуратно опускается на плечо хозяина. Она старается не задеть его острыми коготками, и видно, что птица и человек давно привыкли друг к другу. Священник чуть улыбается краешком губ и поднимает руку. Тонкие пальцы бережно гладят пёструю макушку. Слышен едва уловимый шёпот перьев под его ладонью, и сова прикрывает глаза.",1508,null],[6800,"2026-05-26T20:03:46",23,"эх опять читать....//",1508,null],[6804,"2026-05-26T20:05:15",56,"Ландер Доэ. Священник, что точно отражает волю своего божества, пока другие заботятся о выгоде, он старается остаться человеком в эти трудные времена",6801,null],[6813,"2026-05-26T20:09:27",23,"*слышны маленькие но очень быстренькие ножки которые ему подошли*\n\n*просто подошёл и стоит пялиться в него играя хвостиком*",6804,null],[6820,"2026-05-26T20:11:27",5,"*громко квакаю*",1508,null],[6822,"2026-05-26T20:12:37",61,"*потрепанного вида старец подошел и внимательно слушает*",1508,null],[6825,"2026-05-26T20:13:21",11,"Здравствуйте, святой отец - тихий голос фэйри прозвучал доносимый ветром, между кваканьем",1508,null],[6828,"2026-05-26T20:15:03",56,"Священник, улыбаясь краем губ, протягивает руку вперёд, дабы ощупать тебя. Однако, поняв, что вытянутая рука не дотягивается до тебя, он слегка ахает от удивления, улыбается и начинает опускаться вниз. Твою макушку бережно трогает старая морщинистая рука. Она бархатная, как шёлк. Он аккуратно опускается ниже, начиная ощупывать твоё лицо. Не сильно, просто касается кончиками пальцев. Он мычит с удивлением и любопытством, будто перед ним не старик, а маленький ребёнок.\n— Хммм... Ты не похож на человека. Неужели это чешуя? Кто ты, юнец? Неужели ты пришёл сюда, чтобы помочь мне? Не боишься отправляться в такой путь?\nОн говорит это без упрёка, скорее по-отечески любя, будто мама, что боится отпускать своего ребёнка в лес по грибы: мало ли кто там обитает.",6813,null],[6835,"2026-05-26T20:19:32",44,"// я хз что писать .\n* Я осматриваю всех кто тоже пришел . Лягушка  , маленький кобальт , Виктор корнеплод и Фейрик. Ну все как  обычно  *",1508,null],[6836,"2026-05-26T20:19:33",23,"*Просто кивает когда его рука всё ещё трогает его макушку*\n\n*когда дед убирает руку немного проигрывать на арфе пару струн*\n\n~хочу посмотреть того кто вдохновляет до такой степени и быть таким же чтобы меня всё запомнили! \n\n*по-своему наивная и детская цель но всё же*",6828,null],[6837,"2026-05-26T20:19:50",56,"После того, как он начал ощупывать лицо, он услышал, что к нему обращаются, он поворачивает голову в твою сторону, фейри. Ты делает поклон, по Сану ему не положено, однако людские мерки говорят по-другому. \n— Здравствуйте, не стоит этих формальностей, прошу просто звать меня Ландер. Люблю вспоминать старые дни, когда я был юным\nОн делает лёгкий смешок, поворачивая голову на всех участников. \n— Чувствую, вас здесь очень много. Рад, что старик ещë кому-то не безразличен, хочется мечтать, что так будет вечно. Прошу, герои, её могли бы вы представится? Не могу же я обращаться к вам без имени, это не вежливо! \nОн вновь хихикает, ожидая вашего ответа.",6825,null],[6840,"2026-05-26T20:20:33",5,"// какой твой персонаж?",6835,null],[6842,"2026-05-26T20:21:03",44,"// дварф",6840,null],[6845,"2026-05-26T20:22:40",11,"Фэйри поклонилась в воздухе в ответ\n— Меня зовут Акшиви — представилась она первой",1508,null],[6848,"2026-05-26T20:24:24",61,"*Из высоты около двух метров доносится хриплый старческий голос*\n— Виктор Хакфрухт, можно просто Виктор",1508,null],[6849,"2026-05-26T20:24:29",56,"Он легко похлопывает тебя по макушке. После чего убирает руку.\n— А ты прямо как я в свои годы. Также к нему ходил, он был чуть старше меня, а знал, будто живёт лет сто. Мне нравится твой порыв. Попроси его обучить тебя, меня не стал — говорит мол, не достоин познать пламя.\nОн поворачивается лицом к небу, солнечные лучи нежно обволакивают его морщины.\n— Может, тебе выпадет шанс, попроси его как следует!",6836,null],[6853,"2026-05-26T20:26:38",44,"* я подхожу к нему ,  встал передним и сделал лёгкий поклон .* \n-- меня зовут шуйло . Я помогу  чем смогу",6837,null],[6854,"2026-05-26T20:27:04",23,"*просто начал кивать головой потом понял то что он слепой и не задумываюсь выдал ответ*\n~обязательно , главное его найти!",6849,null],[6855,"2026-05-26T20:27:14",5,"Красный грунг осматривает своих спутников. Он с интересом запоминает особенности каждого из представителей разных рас. В его взгляде на гнома сквозит недоверие.\n\n- Меня называют к'Варсио, святой отец. Прочитав послание, я подумал, что могу узнать много нового для себя и в то же время помочь нуждающимся в помощи",1508,null],[6857,"2026-05-26T20:27:30",56,"Он кланяется тебе в ответ\n—Я буду очень признателен любой помощи",6853,null],[6860,"2026-05-26T20:28:17",11,"*с опаской оглядывается на грунга и старается держать расстояние*",6855,null],[6864,"2026-05-26T20:30:12",23,"-о-о-о я-я-я \n\n*кобальт начал поднимать лапку просто просит всех на секунду обратить на него внимание чтобы самому прокачать своё имя*\n\n-меня меня зовут Манастрель",1508,null],[6865,"2026-05-26T20:30:53",56,"— Хм... Много нового.\n Он задумался, повернув голову к нему, прижал руку к подбородку; теперь проступила его старческая натура. Ранее слегка повзрослевший ребёнок стал стариком, тем самым, которого дети называют ворчливым и угрюмым.\n— Это хорошо, но что именно хочешь узнать? Если хочешь, я могу тебя просветить, хотя бы постараться; просто скажи!",6855,null],[6879,"2026-05-26T20:36:04",5,"— Меня интересуют чужие культуры. Уже находясь в обществе столь разных существ, я узнаю что-то новое. Быть может, и ты мне поведаешь что-то новое о людях",6865,null],[6882,"2026-05-26T20:37:19",23,"*кобальт в это время просто колдует на себе фокусы чтобы согревать себя от чего от него исходит небольшой пар стоит просто играть на арфе слушает всех поглядывает*",1508,null],[6884,"2026-05-26T20:38:03",56,"- Охххх, ясно. Однако, жто лучше почувствовать вживую, ни один рассказ не расскажет тебе о культуре так, как один день проведённый здесь, такова жизнь\nЛандер улыбается тебе, его голос Тихий и спокойный",6879,null],[6885,"2026-05-26T20:38:39",5,"Грунг задумался над его словами и тихо квакнул",6884,null],[6887,"2026-05-26T20:39:59",23,"~а где ваш ученик? \n*просто около его ног уходит играет на арфе тихую мелодию*",6884,null],[6894,"2026-05-26T20:42:46",11,"— Могу ли я поинтересоваться зачем вы собрали всех нас здесь, отец? — произнесла Акшиви, а затем ее взгляд упал на шустрого кобальда",1508,null],[6895,"2026-05-26T20:43:34",56,"— Тим... К сожалению, он не придёт сюда; он ещё ребёнок, нельзя подвергать его такой опасности! Вместо этого он просто поспит час больше, так что он очень этому рад. Он смеётся, после чего ненадолго задумывается.",6887,null],[6898,"2026-05-26T20:44:37",11,"— Разве уже не позднее время для сна? Да и погода чудная. Я уверена ваш ученик насладился бы музыкой этого юного барда",1508,null],[6899,"2026-05-26T20:44:48",5,"При слове \"опасность\" к'Варсио встрепенулся и посмотрел на гнома. Он отлично знал кто здесь на самом деле представлял опасность",1508,null],[6900,"2026-05-26T20:44:59",23,"~АААааааааА\n*звуки понимания и дальше просто продолжает играть на арфе посмотри на остальных*",6895,null],[6902,"2026-05-26T20:46:14",56,"Он неловко поворачивается к тебе, посматривая на свою сову. Она угукает, после чего Ландер обращается к тебе:  \n— Хммм… Я упоминал в сообщении о нахождении моего друга. Его зовут Одри. Он один из немногих поэтов, чьи строки пронизывают самую душу.",6894,null],[6903,"2026-05-26T20:46:24",5,"*совершенно невпопад квакает под звуки мелодии*",6900,null],[6906,"2026-05-26T20:48:23",23,"~он Лич? \n*супер наивно просто смотрят на него*",6902,null],[6907,"2026-05-26T20:48:49",56,"—Я честно говоря не знал, что тут будет такой концерт. Да и времени у нас мало, боюсь представить, что с ним может произойти, поэтому предлагаю отправиться побыстрее, я оплатил повозку, поэтому дорога будет приятной",6898,null],[6908,"2026-05-26T20:49:01",44,"// нет он одри",6906,null],[6909,"2026-05-26T20:49:51",23,"*всё ещё около ног мешается идёт туда-сюда и играет на арфе*\n-да-да пошли",6907,null],[6910,"2026-05-26T20:52:36",5,"— Повозка? Мне нравятся другие способы перемещения\n\nГрунг перестаёт квакать и внезапно прыгает через кобольда. Приземляется и осматривает остальных с довольным видом.",6907,null],[6911,"2026-05-26T20:53:02",11,"Фэйри следует за стариком \n— Простите, но нормально ли оставлять ребенка одного на долгое время? Есть ли кому о нем позаботиться? Говоря о вашем ученике не могу не заметить что мальчик хорошо обучен грамоте для его возраста",6907,null],[6912,"2026-05-26T20:54:00",11,"*испуганно прячется за друидом*",6910,null],[6913,"2026-05-26T20:55:46",61,"*Виктор с невозмутимым видом продолжает внимательно слушать других*",1508,null],[6915,"2026-05-26T20:55:51",23,"*кобальт достаточно маленький чтобы это мог сделать любой*\n\n*кобальд просто обнял ножку жреца в этот момент он испугался и видно что недоволен*",6910,null],[6917,"2026-05-26T20:57:17",5,"*грустно смотрит на реакцию спутников и отправляется в сторону повозки*",1508,null],[6920,"2026-05-26T20:57:38",56,"— Не волнуйтесь, он не один, рядом с ним огромное количество молодых служителей. Я попросил их проследить за учеником, они точно с него глаз не спустят. Честно говоря, я бы сам побоялся их злить, так что он в безопасности. \n*Он легко смеётся, начиная садиться в повозку.* \n— Давайте быстрее! А то без вас уеду! Не оставите же старика умирать у подножия пещеры, прошу! \nОн указывает рукой на другие места.",6911,null],[6923,"2026-05-26T20:58:09",56,"//какого жреца?",6915,null],[6924,"2026-05-26T20:58:18",23,"деда//",6923,null],[6927,"2026-05-26T20:59:13",5,"*смиренно залезает в повозку*",6920,null],[6928,"2026-05-26T20:59:14",23,"*в повозке просто сидит с интересом смотрит на каждого*",1508,null],[6932,"2026-05-26T21:01:01",56,"Он очень удивился этому, но в повозку сел, пусть и с огромным трудом\n— Ну ты конечно старца утомил! Не стыдно! А кто-то собирался в пещеру с драконом идти. А вдруг он как восстанет а потом......\nОн приближается к тебе ты слышишь его дыхание и вдруг........\n— Хвать!\nРезко берёт тебя за морду после чего раздаётся раскатистым смехом, как ребенок, у которого удалась шутка.",6924,null],[6940,"2026-05-26T21:06:27",61,"— Идем\nСпокойно продолжил Виктор\n— Время не ждет",1508,null],[6941,"2026-05-26T21:06:27",11,"Она залетает в повозку и окинув взглядом всех спутников садится на быльце одного из кресел",1508,null],[6942,"2026-05-26T21:07:03",5,"Грунг сидит в повозке, порываясь прыгнуть и квакая от скуки",1508,null],[6943,"2026-05-26T21:07:19",23,"*не против таких шуток и отпустил эти просто сидит просто рядом периодически бьёт хвостом не специально когда мохамед туда-сюда*",6932,null],[6944,"2026-05-26T21:07:33",56,"//ребят, у меня 2 часа, а мне завтра на пару, думаю на сегодня хватит, завтра продолжим с момента с повозкой",1508,null],[6945,"2026-05-26T21:08:08",23,"спокой попки//",1508,null],[6946,"2026-05-26T21:08:24",5,"//окей. Хотелось бы пораньше завтра",1508,null],[6947,"2026-05-26T21:09:06",56,"//я за, просто когда именно?",6946,null],[6948,"2026-05-26T21:10:19",5,"//в 16? я весь день свободен",6947,null],[6949,"2026-05-26T21:10:43",56,"//ну, думаю можно",6948,null],[6950,"2026-05-26T21:11:25",11,"Спокойной ночи",1508,null],[6951,"2026-05-26T21:13:34",61,"//спокойной",1508,null],[6958,"2026-05-26T21:16:58",53,"//спокойной ночи",6944,null],[8290,"2026-05-27T15:39:04",5,"//как у вас дела",1508,null],[8419,"2026-05-27T16:05:25",5,"//где же вы(",1508,null],[8674,"2026-05-27T17:24:44",56,"//блина, сорян,ток щас освободился",1508,null],[8675,"2026-05-27T17:24:49",56,"//вы готовы?",1508,null],[8676,"2026-05-27T17:25:01",5,"//готов",1508,null],[8685,"2026-05-27T17:26:23",56,"//Окей, ждём остальных",1508,null],[8687,"2026-05-27T17:26:40",56,"//сегодня хоть до самого утра, мне завтра в 14 в уник",1508,null],[8700,"2026-05-27T17:30:54",44,"// ну да",8675,null],[8706,"2026-05-27T17:32:17",11,"// Я готова",1508,null],[8707,"2026-05-27T17:32:49",61,"// готов",1508,null],[8709,"2026-05-27T17:34:00",44,"//Пупсик мы тебя ждём  \n@Pro551o",1508,null],[8713,"2026-05-27T17:34:26",23,"готов",1508,null],[8714,"2026-05-27T17:35:02",44,"// @Psinablohastay , все пришли ждем игру",1508,null],[8715,"2026-05-27T17:36:52",56,"//окей",1508,null],[8745,"2026-05-27T17:43:51",56,"Ландер приказывает кучеру. Тот, мужик пусть и не самый старый, но и молодым его не назовёшь, начинает что-то бурчать себе под нос и трогает лошадей. Под его гудение Ландер начинает свой разговор:\n\n— Давным-давно, лет 40 или 45, точно не помню, память дырявая штука. Я встретил его, он вошёл в деревню, полный пафоса. Я всё ещё помню ту почти эльфийскую манеру и взгляд, будто смотрит тебе в душу. Дома своего не имел, поэтому наша церковь его приютила. Помню его голос, громкий, размеренный и очень пронизывающий; рядом с ним будто так и выделялся жар, аж в рот бросало. Многие его слушали, но я ему запомнился больше всех. Говорил, что понимаю искусство лучше других. Ибо я не вижу, что происходит, а чувствую. Тут он отчасти прав, отрицать не буду.\n\nЕго уголки губ поднялись вверх, и он достаёт небольшой свёрток.\n\n— Он говорил: покажи это другим людям, они скажут, видели ли они меня или нет. Как я понял, тут его портрет. Наверное, сейчас он изменился, но вам всё равно лучше посмотреть. Что скажете?\n\nОн поворачивается к вам с фотографией, ожидая вашего ответа.",1508,null],[8753,"2026-05-27T17:46:05",23,"-не не видел \n*сидит смотрит в окно*",1508,null],[8754,"2026-05-27T17:46:07",11,"Фея взлетает со своего места что бы рассмотреть фотографию\n— Вы правы, нам нужно знать кого мы ищем",1508,null],[8756,"2026-05-27T17:46:36",11,"— Для меня он так же не выглядят знакомо",1508,null],[8757,"2026-05-27T17:47:05",11,"*Она отстранилась давая посмотреть на фото другим*",1508,null],[8758,"2026-05-27T17:48:06",56,"Он показывает тебе портрет\n— Вот он, я показывал еë в трактире, мне быстро указывали на человек, говорили, что он сидел в углу, даже провожали до него, как сейчас помню. Только однажды его никто не видел, и так до сих пор",1508,null],[8759,"2026-05-27T17:48:29",44,"// я думал что все эльфы выглядят как фембой",8758,null],[8760,"2026-05-27T17:48:30",5,"Грунг пристально смотрит в глаза изображенного поэта, пытаясь разгадать его секреты. Затем отстраняется, глубоко задумавшись и не произнося ни слова",1508,null],[8761,"2026-05-27T17:50:13",11,"// даже не квакнув?",1508,null],[8762,"2026-05-27T17:50:32",61,"*Виктор внимательно рассматривает фотографию прищурившись*\n— Не видел, боюсь я в целом мало людей видел в жизни, я предпочитаю уединенный образ жизни",1508,null],[8763,"2026-05-27T17:51:04",5,"// нет, даже не квакнув",8761,null],[8764,"2026-05-27T17:51:07",23,"-крутой живот....\n*просто одним глазком посмотрел и снова смотрит в окно*",1508,null],[8765,"2026-05-27T17:51:36",11,"*С подозрением косится на кобальда*",1508,null],[8766,"2026-05-27T17:53:17",5,"*смотрит на живот кобольда*",8764,null],[8767,"2026-05-27T17:54:21",44,"* осматриваю портрет , понимаю что этот эльф был не как все эльф , он больше мужественный , чем другие .*\n------  такого необычного эльфа мы быстро найдем.  знаете где вы последний раз видели ? \n\n// Наверное я все правильно понял",1508,null],[8768,"2026-05-27T17:54:39",23,"а у меня свет отключили//",8765,null],[8769,"2026-05-27T17:54:39",23,"сеть как понимаете тоже ушла//",1508,null],[8770,"2026-05-27T17:54:55",44,"// все правильно",8769,null],[8771,"2026-05-27T17:55:48",56,"— Понимаю, ничего страшного\nОн убирает фотографию обратно к себе, после чего вновь посматривает на вас —все в порядке, ничего страшного.",1508,null],[8772,"2026-05-27T17:56:21",5,"— Как такой огромный человек мог пропасть?",1508,null],[8774,"2026-05-27T17:56:34",23,"*примерно так сидит*",1508,null],[8776,"2026-05-27T17:57:21",44,"// вы нечего не видели",1508,null],[8777,"2026-05-27T17:57:21",56,"— Эльфа, сомневаюсь что это эльф, говорили все, что человек, но вам виднее, как ни крути",8767,null],[8778,"2026-05-27T17:57:57",23,"~наверное он уже умер от старости \n*так просто невзначай сказал*",1508,null],[8779,"2026-05-27T17:58:12",44,"// значит всё-таки не так понял его рассказ",8777,null],[8780,"2026-05-27T17:58:40",11,"Задумавшись фея произнесла:\n— В письме вы указали что предполагаете где он может находиться. Могли бы вы побольше нам рассказать об этом месте? — Услышав слова кобальда она так же добавила — И как давно вы в последний раз его видели? Сколько ему было лет тогда?",1508,null],[8781,"2026-05-27T17:59:11",44,"// ну принцепи оправдывает 8 интеллекта",8779,null],[8782,"2026-05-27T18:01:07",11,"— И разве это большая проблема если он мертв? — Пробормотала она себе под нос",1508,null],[8783,"2026-05-27T18:01:28",56,"— Я ходил к нему почти два года. После этого он пропал. Только в пещере я вновь почувствовал тепло, тепло сердца. Поэтому я уверен, что он там. Буду рад, если проверите. Только прошу, будьте бдительны: раньше там жил дракон, наверное, за его пожитками точно кто-то охотится.",8780,null],[8784,"2026-05-27T18:02:03",5,"*Грунг внимательно посмотрел на фэйри, пытаясь понять сказанное*",8782,null],[8785,"2026-05-27T18:02:18",23,"~Может вы просто достали его?",8783,null],[8786,"2026-05-27T18:03:32",5,"— Отец, вы почувствовали тепло сердца просто в какой-то пещере? Что же такого особенного в ней?",8783,null],[8787,"2026-05-27T18:03:33",11,"— Учту и постараюсь помочь как смогу — серьёзно произнесла она — как долго нам ещё ехать?",8783,null],[8788,"2026-05-27T18:03:54",56,"* Он вовсе не обижен, он даже смеется от твоих слов.*\n— Трудно сказать. Тогда бы его достали абсолютно все. Он мало к кому привязывался, всегда был холоден",8785,null],[8789,"2026-05-27T18:05:02",44,"* когда услышал про дракона у него появилась большая  улыбка, осознание что он сможет сразится с сильным врагом  *\n---- не переживайте , на всякий случай проверим пещеру , вдруг он правду там.",8788,null],[8790,"2026-05-27T18:05:05",56,"—Довольно долго\n*говорит священник с усталым видом*\n— Если хотите, то можете отдохнуть, прибудем мы туда уже к вечеру. Там вам отдыхать мало кто даст",8787,null],[8791,"2026-05-27T18:06:13",61,"— Мертв он или нет, но мы обязаны найти его\n*Внезапно сказал друид*\n— Я чувствую что его поиски каким-то образом важны для поддержания баланса в природе",1508,null],[8792,"2026-05-27T18:06:15",5,"— И всё-таки, что это за пещера такая?\n\nГрунг становится подозрительным.",1508,null],[8793,"2026-05-27T18:06:22",11,"— Сколько тебе лет.. Манастрель? — имя она произнесла чуть погодя, вспоминая его",8785,null],[8794,"2026-05-27T18:07:05",23,"-Я уже достаточно старый",8793,null],[8795,"2026-05-27T18:07:09",23,"-10 лет",1508,null],[8796,"2026-05-27T18:07:21",23,"-думаю поживу ещё года 5 и умру",1508,null],[8797,"2026-05-27T18:08:01",23,"*кобальты хоть и живут до 120 лет часто не доживают до 30 и взрослые это уже в 6 //",1508,null],[8798,"2026-05-27T18:08:08",5,"— Серьёзный возраст и в правду",8795,null],[8799,"2026-05-27T18:08:10",44,"//примерные у меня такие планы на жизнь",8796,null],[8800,"2026-05-27T18:08:54",11,"— Ночь в пещере звучит действительно не безопасно. Полагаю стоит подготовиться? Что на счёт факелов?",8790,null],[8801,"2026-05-27T18:09:11",56,"— По древним преданиям, три героя давно одолели обезумевшего дракона, обитавшего там, и теперь это место пустует. Однако я не думаю, что он пошёл туда по своей воле. Боюсь, его украли и оставили там, хотя я в этом и не уверен.",8792,null],[8803,"2026-05-27T18:09:24",11,"Последний вопрос фея произнесла переведя взгляд на спутников",1508,null],[8804,"2026-05-27T18:09:27",44,"-- да я с тобой согласен, я бы взял ещё масло",8800,null],[8805,"2026-05-27T18:09:30",23,"~эээ..... \n*явно недовольство светом*",8800,null],[8807,"2026-05-27T18:09:51",23,"~Ну ладно потерплю мне не впервой \n*всё ещё продолжает смотреть в окно щуриться*",1508,null],[8808,"2026-05-27T18:10:13",5,"//  а можно сделать проверку на проницательность против жреца?",8801,null],[8809,"2026-05-27T18:10:25",11,"Получив ответ Акшиви задумалась о том что он слишком ребячится для своего возраста, но решила не произносить этого вслух.",8797,null],[8810,"2026-05-27T18:10:48",61,"— Факелы у меня есть и трутница, если нужно будет развести костер",8803,null],[8812,"2026-05-27T18:11:00",23,"~все нашу с собой \n*показывает на арфу *",1508,null],[8814,"2026-05-27T18:11:36",56,"//делай",8808,null],[8815,"2026-05-27T18:11:56",44,"// значит мы не будем брать масло , а жаль , так хотел что враги горели и кричали в огоние",1508,null],[8816,"2026-05-27T18:12:14",11,"— Я думаю что могу помочь зажечь факела без масла \n// Могу ведь? С помощью фокусов",8804,null],[8817,"2026-05-27T18:12:42",5,"Грунг ещё раз вспоминает всё сказанное жрецом и вглядывается в его лицо, чтобы понять, не кривит ли тот душой",1508,null],[8819,"2026-05-27T18:12:56",5,"// а как делать",1508,null],[8820,"2026-05-27T18:13:31",44,"// ты не понимаешь прикола масло , масло увеличивает урон огня по противнику",8816,null],[8822,"2026-05-27T18:13:45",56,"/r d20+модификатор",1508,null],[8824,"2026-05-27T18:13:50",11,"// Тогда нам нужно масло😳",1508,null],[8826,"2026-05-27T18:14:02",5,"/r d20+3",1508,null],[8829,"2026-05-27T18:14:44",56,"ты не можешь понять, что он тебе говорит, правду или ложь",8826,null],[8831,"2026-05-27T18:15:20",5,"к'Варсио раздражённо квакает, так и не сумев ничего понять",8829,null],[8834,"2026-05-27T18:15:45",44,"// ооо понял могущество масло",8824,null],[8836,"2026-05-27T18:16:03",23,"меня сеть тарабанит//",1508,null],[8837,"2026-05-27T18:16:29",44,"// как грубо или нежно ?",8836,null],[8839,"2026-05-27T18:16:52",23,"переменчиво//",1508,null],[8841,"2026-05-27T18:17:07",56,"— Ну что, ребятки, остались ли ещё вопросы, а то я как-то устал немного, вы не будете против, если я вздремну немного?",1508,null],[8843,"2026-05-27T18:17:25",23,"~будем",8841,null],[8845,"2026-05-27T18:17:37",11,"Фея последовала примеру спутника и заняв свое предыдущее место она уставилась в окно обдумывая предстоящее приключение и полученную информацию",1508,null],[8847,"2026-05-27T18:17:41",23,"~ты не сказал Что за дракон",8841,null],[8849,"2026-05-27T18:17:55",5,"Красный грунг отворачивается и молчит",1508,null],[8850,"2026-05-27T18:18:02",23,"*просто заинтересованы присел перестал смотреть в окно Но всё ещё хвостом периодически бьёт старика не специально*",8847,null],[8855,"2026-05-27T18:18:40",11,"// это можно считать за урон ?",8850,null],[8860,"2026-05-27T18:19:45",56,"— Дракон? Хммм... Я особо много о нём не знаю. Красный дракон, который когда-то поклялся защищать город в обмен на неприкосновенность его драгоценностей, но вскоре он оказался невероятно яростным, настолько, что представлял угрозу для города. Трое героев обещали положить этому конец и одолели чудовище. После этого о драконе никто не слышал.",8847,null],[8863,"2026-05-27T18:20:19",44,"// бли , значит на него масло нету смысла тратить",8860,null],[8864,"2026-05-27T18:20:40",11,"Теперь Акшиви думала о том что изучить кости дракона было бы полезно для ее исследований",1508,null],[8865,"2026-05-27T18:20:41",23,"неа//",8855,null],[8866,"2026-05-27T18:21:27",23,"видимо дальше без меня//",1508,null],[8867,"2026-05-27T18:21:42",11,"— В чем проявилась ярость этого существа?",8860,null],[8868,"2026-05-27T18:21:56",23,"-огнем очевидно",8867,null],[8869,"2026-05-27T18:22:19",11,"// тогда масло сыграет против нас",1508,null],[8872,"2026-05-27T18:22:44",44,"// вот по этому нет смысла на него масло тратить",8869,null],[8873,"2026-05-27T18:23:01",11,"// Отмена тогда поджигать будем факела без масла",1508,null],[8876,"2026-05-27T18:24:01",56,"По словам очевидцев, он мог выйти из пещеры и сжечь тех, кто просто проходил мимо. Вскоре ему этого стало недостаточно, и он начал сжигать поселения, пока этому не положили конец.",8867,null],[8878,"2026-05-27T18:24:34",23,"чуааки у меня 5% и сеть ебет // Короче передаю своего перса мастеру //",1508,null],[8879,"2026-05-27T18:24:52",23,"сыграю сколько смогу потом пропаду//",1508,null],[8880,"2026-05-27T18:24:56",56,"// ЕПРСТ",8878,null],[8881,"2026-05-27T18:25:07",11,"// rip",8879,null],[8882,"2026-05-27T18:25:10",23,"да жопа боль//",8880,null],[8884,"2026-05-27T18:25:32",23,"даже обидно то что вроде играла вот эти всё прикольно А вроде В итоге ничего//",1508,null],[8886,"2026-05-27T18:25:56",61,"Друид вдруг задумался\n\n— Вы говорили что ощутили огонь когда нашли эту пещеру...",8876,null],[8887,"2026-05-27T18:26:13",23,"-а дракон огненный правильно думаете....",1508,null],[8888,"2026-05-27T18:26:30",11,"— Интересно что подтолкнуло это существо нарушить свое общение, возможно что-то стало этому причиной? — Она обращалась скорее к себе чем к кому-то из присутствующих — Было бы хорошо если бы я могла спросить это у него лично..",8876,null],[8889,"2026-05-27T18:26:32",23,"-скорее всего дедан ошибся но это не точно пойдём посмотрим в любом случае",1508,null],[8890,"2026-05-27T18:26:55",23,"~было бы плохо если бы мы встретили дракона который всё ещё в ярости",8888,null],[8891,"2026-05-27T18:27:10",23,"~было бы ещё хуже напоминать о нём скорее всего у него что-то украли",1508,null],[8893,"2026-05-27T18:27:17",11,"// Я думаю как некромант который бы хотел поговорить с мертвым драконом",8890,null],[8894,"2026-05-27T18:27:32",5,"— Никакого дракона там нет — заявил грунг, повернувшись к остальным",1508,null],[8896,"2026-05-27T18:27:45",56,"—Конечно, как пожелаете, только он уже давно мёртв. Не знаю, у кого вы будете спрашивать.",8888,null],[8897,"2026-05-27T18:27:49",11,"— Почему ты так в этом уверен?",8894,null],[8900,"2026-05-27T18:28:18",11,"// Способности говорить с мертвыми ведь существуют если я не ошибаюсь? Правда у меня их пока нет:(",8896,null],[8901,"2026-05-27T18:28:29",11,"// Так что пока я просто подумаю об этом..",1508,null],[8902,"2026-05-27T18:28:30",56,"//да, существуют",8900,null],[8903,"2026-05-27T18:28:31",5,"к'Варсио кивнул на слова старика, сочтя это достаточным ответом",8896,null],[8904,"2026-05-27T18:28:45",44,"// вродебы да , а вродебы нету , а вродебы да ,наверное да",8900,null],[8905,"2026-05-27T18:28:55",23,"Да есть заклинание разговор с мёртвыми//",1508,null],[8907,"2026-05-27T18:29:07",23,"перепутал//",1508,null],[8908,"2026-05-27T18:29:22",11,"// это то что мне надо 💅",8905,null],[8913,"2026-05-27T18:29:52",23,"всего пять вопросов//",8908,null],[8914,"2026-05-27T18:30:00",23,"на который труп не обязан отвечать нормально/",1508,null],[8915,"2026-05-27T18:30:00",11,"// я знаю, но я отыгрываю некроманта-волшебника который пока что может только думать об этом:о",1508,null],[8919,"2026-05-27T18:30:31",44,"// а разве он должен всегда отвечать , ну типа вы видели тот прикол ?",8914,null],[8920,"2026-05-27T18:31:11",56,"*глаза Ландера уже начинают слипаться, пожилой возраст даёт о себе знать. *\n— Буду рад, если вы зададите все вопросы, что ещë остались, а то, уже не могу, сидеть нормально.......",1508,null],[8923,"2026-05-27T18:32:08",61,"— Если дракон еще жив, это бы объяснило почему я ощущаю такое беспокойство здешних лесов\n\nС явной тревогой сказал друид",1508,null],[8932,"2026-05-27T18:33:30",23,"~Ладно спи уже \n\n*не сильно просто толкает старика в сторону чтобы он оплатился не на кобальда*",8920,null],[8938,"2026-05-27T18:37:01",44,"// ну давай сделаем таймскип до пещеры , если у вас ещё вопросов не осталось",1508,null],[8939,"2026-05-27T18:37:13",5,"// поддерживаю",1508,null],[8941,"2026-05-27T18:37:24",61,"— Честно сказать, я бы тоже не против отдохнуть, если вы не против\n\nС этими словами друид закрыл глаза и начал тихо сопеть",1508,null],[8942,"2026-05-27T18:37:30",56,"— Благодарю, оставлю вас наедине, Если вы не против\n* Его глаза начинают слипаться и он окончательно засыпает, скорее всего, он вас даже не слышит*",1508,null],[8943,"2026-05-27T18:37:37",61,"// да",1508,null],[8949,"2026-05-27T18:39:40",56,"//что делают остальные?",1508,null],[8950,"2026-05-27T18:40:22",61,"//я тоже приляг, пенсия все таки",1508,null],[8951,"2026-05-27T18:40:24",11,"// Если я не ошибаюсь то феи не спят? Я думаю просто погрузится в свои мысли",1508,null],[8952,"2026-05-27T18:40:42",5,"Грунг расслабленно сидит в полусне, периодически осматривая спутников",1508,null],[8954,"2026-05-27T18:44:20",44,"//него жду когда приедем",8949,null],[8955,"2026-05-27T18:46:57",56,"Каждый из вас погружается в сон. Кучер перестаёт что-то бормотать и останавливает телегу.\n— Приехали, — говорит он вам, в частности священнику. Он просыпается и начинает пробуждать вас ото сна.\n— Прошу, герои, мы прибыли. Надеюсь, вас не укачало?\nОн выходит оттуда. В 500 футах от вас вы видите горы, в которых находится пещера.\n— Там! Там тепло, прошу.\nОн начинает идти к вашему удивлению, спотыкаясь обо все камни, учитывая, что местность тут не самая ровная.",1508,null],[8956,"2026-05-27T18:47:58",5,"Красная лягушка немедленно начинает прыгать по направлению к горам",1508,null],[8957,"2026-05-27T18:49:39",5,"Он проходит 100 футов, затем оборачивается и смотрит на спутников",1508,null],[8958,"2026-05-27T18:50:21",61,"— позвольте вам помочь\n\n*Увидев походку жреца предложил друид*",1508,null],[8959,"2026-05-27T18:50:21",23,"*очень лень идти*",8955,null],[8960,"2026-05-27T18:50:45",23,"*ритуалом просто спавнит несколько невидимых слуг чтобы они его потащили*",1508,null],[8961,"2026-05-27T18:50:59",11,"Выбравшись с повозки фея осматривает местность вокруг // что мы видим? \\\\\nОна замечает что старик спотыкается, но не знает чем помочь",1508,null],[8962,"2026-05-27T18:51:02",23,"*кобальт просто улетает в лежачем состоянии*",1508,null],[8963,"2026-05-27T18:51:06",11,"// так вот откуда пузо взялось",8960,null],[8965,"2026-05-27T18:51:39",23,"Нет просто он неправильно сел он слишком худой для пуза///",8963,null],[8968,"2026-05-27T18:52:26",5,"// а кобольд не слишком тяжёлый для слуг?",1508,null],[8969,"2026-05-27T18:52:27",44,"* смотрю на гору и не дождусь сразится с сильными врагами . Кладу свой двуручный мечь на плече и иду за стариком *",8955,null],[8971,"2026-05-27T18:56:37",56,"— Буду очень признателен\n* Он кивает друга, позволяя себя довести до входа в пещеру*",8958,null],[8974,"2026-05-27T18:57:43",5,"Грунг ждёт остальных у входа в пещеру, периодически квакая",1508,null],[8976,"2026-05-27T18:57:53",56,"Местность окружена лесом, спереди находиться довольно большая гора с небольшим выступом, в котором находится вход в пещеру.",8961,null],[8980,"2026-05-27T18:58:39",11,"*Следует за остальными*",1508,null],[8984,"2026-05-27T19:01:10",56,"* Ландер прикасается к стенам пещеры, там на удивление сухо, даже слишком, это обычно не естественно для пещер. Он прижимает руку к сердцу, начиная улыбаться. \n— Да! Это оно! То самое тепло, только оно слабое, как весенние лучи, он там, но далеко. Прошу, герои, найдите его, умоляю, только так я могу спать спокойно.",1508,null],[8986,"2026-05-27T19:02:01",5,"Грунг прикладывает лапку к стене, а затем резко отдёргивает",1508,null],[8987,"2026-05-27T19:02:08",5,"— И правда, тёплая...",1508,null],[8989,"2026-05-27T19:02:44",5,"Он вглядывается в глубь пещеры, пытаясь найти следы живых существ",1508,null],[8990,"2026-05-27T19:02:57",5,"// проверка восприятия",1508,null],[8992,"2026-05-27T19:03:12",56,"//кидай",8990,null],[8993,"2026-05-27T19:03:22",5,"/r d20+2",1508,null],[8995,"2026-05-27T19:03:24",11,"— Полагаю пора достать факела, товарищи — она заглядывает в темень пещеры вслед за грунгом",1508,null],[8997,"2026-05-27T19:04:16",44,"* я прикасаясь касаюсь к к стенам пещеры и думаю а иза чего они могли так нагревается*\n// Анализ, природа или восприятие?",8984,null],[9000,"2026-05-27T19:04:31",56,"*ты не можешь понять, кто или что здесь находилось",8994,null],[9002,"2026-05-27T19:04:46",56,"//природа или анализ, что больше",8997,null],[9003,"2026-05-27T19:05:23",44,"// проверка природы",9002,null],[9004,"2026-05-27T19:05:29",44,"/r 1d20+1",9003,null],[9007,"2026-05-27T19:05:42",44,"// блятские четверки",9005,null],[9013,"2026-05-27T19:06:33",56,"//остальные кидать не будут? я хочу фулл хаус",1508,null],[9022,"2026-05-27T19:07:37",11,"// Анализ значит?",1508,null],[9023,"2026-05-27T19:07:38",5,"// а можно другим то же самое кидать?",1508,null],[9024,"2026-05-27T19:07:59",56,"//ебашь",9022,null],[9025,"2026-05-27T19:08:04",11,"/rd20 + 5",1508,null],[9026,"2026-05-27T19:08:05",56,"//да уже пофиг",9023,null],[9028,"2026-05-27T19:08:14",56,"/r d20 + 5",1508,null],[9031,"2026-05-27T19:08:28",56,"//кидай",1508,null],[9037,"2026-05-27T19:09:20",11,"// Мхм, ты кинул за меня или мне ещё раз попробовать? Сори я додик",9031,null],[9040,"2026-05-27T19:09:31",61,"// мне ждать, или кидать тоже?",1508,null],[9042,"2026-05-27T19:09:57",56,"//кидай ты, я просто показал как кидать",9037,null],[9045,"2026-05-27T19:10:07",56,"//как хочешь",9040,null],[9048,"2026-05-27T19:10:22",11,"/r d20 + 5",1508,null],[9053,"2026-05-27T19:10:36",61,"// тогда природу",1508,null],[9059,"2026-05-27T19:11:02",56,"//блявхаххвхвхахвх",1508,null],[9060,"2026-05-27T19:11:08",61,"*друид закрыл глаза и внимательно слушает*",1508,null],[9061,"2026-05-27T19:11:10",56,"//пжпжпжпжп, завали и ты",9053,null],[9062,"2026-05-27T19:11:12",5,"— Итак, у нас пещера с тёплыми стенами, которые как-то связаны с пропавшим человеком. Что думаете об этом?",1508,null],[9063,"2026-05-27T19:11:18",61,"/r d20+4",1508,null],[9065,"2026-05-27T19:11:32",61,"// да епт",1508,null],[9066,"2026-05-27T19:11:41",61,"// подкручено",1508,null],[9067,"2026-05-27T19:11:42",5,"// идём вслпеую",1508,null],[9069,"2026-05-27T19:11:54",56,"//ПХАХАХАХАХСХАХХ",1508,null],[9070,"2026-05-27T19:12:02",11,"// Ну это мем",1508,null],[9072,"2026-05-27T19:12:15",11,"// А Манестрель?",1508,null],[9076,"2026-05-27T19:13:15",56,"//ладно, за Ландер кинет",1508,null],[9078,"2026-05-27T19:13:26",56,"//верьте в деда",1508,null],[9079,"2026-05-27T19:13:26",11,"// щас 20 будет",1508,null],[9080,"2026-05-27T19:13:43",56,"/roll d20+4",1508,null],[9084,"2026-05-27T19:13:53",56,"//ПХАХАХАХАХАХПХПХХПАХХПМХХ",1508,null],[9085,"2026-05-27T19:14:08",44,"* мы поняли что  пещера просто заболела  и поднялась температура *",1508,null],[9087,"2026-05-27T19:14:14",5,"// примите что мы ничего не знаем о пещере",1508,null],[9104,"2026-05-27T19:18:21",56,"Ландер остаётся у прохода, не идя вперёд.  \n— Вы уж простите, однако от слепого человека будет мало толку. Надеюсь, вы вернётесь живыми. Если что, попросите вашего союзника послать за мной слугу. Я же всё правильно понял?  \n*Он улыбается вашему магу лёгкой и непринуждённой улыбкой, максимально искренней и детской.*  \n— Я буду ждать вас у входа. Прошу, возвращайтесь живыми.  \n*Он держится за священный символ, наполняя ваши тела светом.*  \n[Заклинание благословения]  \n//Возрадуйтесь, челядь, над вами решили не потешиться.(пока что)",1508,null],[9106,"2026-05-27T19:19:15",5,"// это он говорит челядь??",1508,null],[9109,"2026-05-27T19:19:24",11,"//Над нами уже потешился ранальд",1508,null],[9111,"2026-05-27T19:20:12",56,"//ненене, ошибся",9106,null],[9112,"2026-05-27T19:20:24",56,"//это мастер потешиться",1508,null],[9113,"2026-05-27T19:20:29",5,"// хд",1508,null],[9114,"2026-05-27T19:20:36",56,"//просто не тот знак поставмл",1508,null],[9115,"2026-05-27T19:20:55",11,"— Благодарю за благословение, господин Ландер — Она поклонилась ему, хотя и знала что он этого не увидит — Полагаю пора идти внутрь — Теперь Фейри обратилась к спутникам, залетая в пещеру",1508,null],[9118,"2026-05-27T19:21:08",5,"Грунг достаёт факел",1508,null],[9120,"2026-05-27T19:21:27",5,"— Кто там умелец зажигать огонь?",1508,null],[9121,"2026-05-27T19:21:40",11,"*Зажигает факел в руках жабки с помощью фокуса*",1508,null],[9122,"2026-05-27T19:21:53",11,"// я хз как правильно заговоры юзать 🫪",1508,null],[9123,"2026-05-27T19:22:48",56,"//просто юзай, всë",1508,null],[9124,"2026-05-27T19:22:57",44,"--- благодарю за дар , она будет на полезна .\n// Вряд-ли что-то случится за минуту",9104,null],[9128,"2026-05-27T19:24:15",5,"— Постараемся вернуться, святой отец. Полагаю, мы готовы?",1508,null],[9130,"2026-05-27T19:24:16",11,"— Веди, К'варсио, раз уж факел у тебя — Она подлетела к грунгу, но стараясь соблюдать дистанцию опасаясь повадок его расы",1508,null],[9136,"2026-05-27T19:25:10",61,"— Благодарю вас, не волнуйтесь я сделаю все что в моих силах чтобы найти вашего друга\n\n*поворачивается к остальным*\n\n— Вперед друзья",1508,null],[9138,"2026-05-27T19:25:20",56,"//вы двигаетесь дальше?",1508,null],[9139,"2026-05-27T19:25:30",11,"// угу",1508,null],[9140,"2026-05-27T19:25:31",5,"*направляется вперёд, убедившись, что остальные следуют*",1508,null],[9141,"2026-05-27T19:25:36",44,"// а как по твоему мы можем получить тпка ?",9138,null],[9154,"2026-05-27T19:29:49",56,"Проходя дальше, начинает становиться всë жарче и жарче, вы видите какие-то символы драконы, по стенам, они встречаются чаще и чаще, пока вы проходите вперёд, пока не упираетесь в дверь, вы понимаете, другого пути нет, нужно идти вперёд, рядом какой-то артефакт, в котором указаны цифры от 1 до 9,вы продолжайте видеть эти символы, над дверью бронзовая голова дракона и пару листков, что валяются у входа",1508,null],[9158,"2026-05-27T19:30:19",5,"— Кто-нибудь знает, что это за штуковина?",1508,null],[9163,"2026-05-27T19:30:49",5,"*переминается с ноги на ногу от неприятной жары*",1508,null],[9166,"2026-05-27T19:31:14",44,"* я походу к артефакту и осматриваю его всех сторон чтобы понять что оно вообще делает ? *\n// Как понимаю на магию ?",9154,null],[9168,"2026-05-27T19:31:47",56,"//Агась",1508,null],[9169,"2026-05-27T19:31:59",5,"Грунг нагибается, подбирает листки и подносит к свету, пытаясь прочесть",1508,null],[9171,"2026-05-27T19:32:08",5,"// надо проверку?",1508,null],[9172,"2026-05-27T19:32:17",44,"/r 1d20-1",9166,null],[9174,"2026-05-27T19:32:38",11,"— Дверь в пещере, ещё и артефакт, она однозначно не обычная — Фейри облетает вокруг двери и осматривает артефакт",1508,null],[9179,"2026-05-27T19:33:20",11,"/r d20+5",1508,null],[9181,"2026-05-27T19:33:26",44,"* я понимаю что это обычный камень с цифрами*",9173,null],[9182,"2026-05-27T19:33:27",56,"//нет, не нужно",9171,null],[9183,"2026-05-27T19:33:41",56,"//Агась",9181,null],[9187,"2026-05-27T19:34:26",56,"*кажется, нужно что-то ввести, чтобы дверь открылась, однако кто знает код*",9180,null],[9188,"2026-05-27T19:34:36",61,"*Виктор молча стоит и рассматривает дверь*",1508,null],[9190,"2026-05-27T19:35:13",44,"// Блин что я мучаюсь , у меня есть заклинание которые открывает любую дверь",1508,null],[9191,"2026-05-27T19:35:30",11,"// Нам нужно найти подсказки к коду где-то в пещере?",1508,null],[9195,"2026-05-27T19:36:03",5,"// а что на листках",1508,null],[9198,"2026-05-27T19:36:41",56,"Там надпись, поворачивая его ты замечаешь, что с одной стороны он прожженной чем-то Непонятным, а с другой стороны написано послание кровью\nЯ помню пару глаз, что смотрели на меня\nПару ног, что уводили в пляс\nДва близнеца водили хороводы, но средь бела дня\nНастигла пустота и я угась\nТаким была надпись на нём",9169,null],[9202,"2026-05-27T19:37:11",44,"* я подхожу к двери ,  берусь за ручку и бытаюсь открыть с применение заклинание ( открывание двери с помощью атлетика )*",9190,null],[9204,"2026-05-27T19:37:44",56,"//ну да, ну да, пошёл я нахер",9202,null],[9205,"2026-05-27T19:37:54",56,"//что за заклинание?",9202,null],[9206,"2026-05-27T19:38:04",5,"Грунг читает слова вслух, в конце квакая",9198,null],[9207,"2026-05-27T19:38:06",11,"// Да нам тоже интересно",9205,null],[9208,"2026-05-27T19:38:11",56,"//да, код из 6 цифр",9191,null],[9209,"2026-05-27T19:38:11",44,"// я сказал открывание двери с помощью атлетики",9205,null],[9212,"2026-05-27T19:38:26",56,"//ааааа",9209,null],[9214,"2026-05-27T19:38:39",56,"// кидай, спас на ловкость",1508,null],[9215,"2026-05-27T19:38:49",44,"// а причем тут ловкость ?",9214,null],[9216,"2026-05-27T19:39:00",5,"// ;)",1508,null],[9217,"2026-05-27T19:39:04",56,"//узнаешь)",1508,null],[9220,"2026-05-27T19:39:39",44,"/r 1d20-1",9217,null],[9224,"2026-05-27T19:40:03",56,"//бляяяяять",9221,null],[9228,"2026-05-27T19:40:13",56,"//худи вам так не везёт?",1508,null],[9229,"2026-05-27T19:40:13",11,"// это как будто уже канон для наших роллов",1508,null],[9231,"2026-05-27T19:40:20",56,"/r 2d6",1508,null],[9236,"2026-05-27T19:41:15",5,"// почему 2 раза",1508,null],[9237,"2026-05-27T19:41:24",56,"Бронзовый дракон, что стоит сверху двери тут же октывает тебя пламенем, на твоих руках появляются ожого\n//отбери 3 хп",9222,null],[9238,"2026-05-27T19:41:31",44,"// потому что второй раз я кинул по приколу",9236,null],[9239,"2026-05-27T19:41:39",56,"//я всё видел",1508,null],[9240,"2026-05-27T19:41:47",56,"//отбираю 11 хп?",1508,null],[9242,"2026-05-27T19:42:43",44,"//так 11 или 3?",1508,null],[9244,"2026-05-27T19:43:00",5,"Грунг от неожиданности подпрыгивает на месте и с тревогой смотрит на дварфа.",1508,null],[9245,"2026-05-27T19:43:09",56,"//3 хп, успокойся",9242,null],[9247,"2026-05-27T19:43:29",61,"*друид смотря на гнома недовольно покачал головой*",1508,null],[9248,"2026-05-27T19:43:37",5,"— Ты в поря... — Жабка не договаривает слова и внезапно улыбается",1508,null],[9249,"2026-05-27T19:43:39",44,"// да просто я все равно мох на фул отхилится",9245,null],[9251,"2026-05-27T19:44:58",44,"* я убираю   огонь на своем кольчуге *\n--- ну теперь мы знаем что будет если не правильно вести код",9232,null],[9254,"2026-05-27T19:45:28",56,"//решайте загадку",1508,null],[9259,"2026-05-27T19:46:21",5,"— Давайте подумаем над текстом на бумагах",1508,null],[9260,"2026-05-27T19:46:24",11,"// Что вокруг нас находится кроме двери? Это что-то типа коридора узкого?",1508,null],[9264,"2026-05-27T19:47:14",44,"// я использую наложение рук на себя и трачу там один запас \n* Я касаюсь  на свою обоженую  часть тела и востонавливать его с своей силой *\n// Восстанавливаю себе хп 1+3",9254,null],[9267,"2026-05-27T19:47:52",56,"//да, всë верно",9260,null],[9268,"2026-05-27T19:47:53",11,"Фея задумалась о словах про глаза и осматривает глаза дракона на двери",1508,null],[9270,"2026-05-27T19:48:33",5,"к'Варсио пытается понять что значат слова \"два близнеца\"",9198,null],[9271,"2026-05-27T19:48:40",5,"// проверка анализа?",1508,null],[9273,"2026-05-27T19:48:56",56,"//давайте",1508,null],[9274,"2026-05-27T19:49:08",5,"/r d20-1",1508,null],[9276,"2026-05-27T19:49:47",44,"// 2 , 3, 2, 0  , думаю такой ответ",9198,null],[9278,"2026-05-27T19:50:11",11,"— Могут ли слова \"пара\" и \"два\" значить цифры тода? — задумчиво сказала фея — Так же меня интересуют слова про свет, возможно нам стоит посветить на глаза дракона и посмотреть что из этого выйдет?",1508,null],[9279,"2026-05-27T19:50:26",56,"//в двери указано 6 цифр, скорее всего, строки прячут в себе эти цифры, но где какие непонятно",9275,null],[9282,"2026-05-27T19:50:45",44,"// вообще нет , там нужно 6 цифер .",9276,null],[9286,"2026-05-27T19:51:12",5,"— Я знаю ответ!",1508,null],[9287,"2026-05-27T19:51:18",11,"// вопрос могу ли я использовать заговор что бы ввести код не получая урон? Если ответ не верный",1508,null],[9288,"2026-05-27T19:51:37",56,"//что за заговор?",9287,null],[9289,"2026-05-27T19:51:53",36,"//хуисосы",9288,null],[9291,"2026-05-27T19:51:53",44,"// у меня ещё много хп , так что я буду вести код",9287,null],[9292,"2026-05-27T19:51:53",5,"224200",1508,null],[9293,"2026-05-27T19:52:03",5,"—Есть желающие попробовать?",1508,null],[9296,"2026-05-27T19:52:29",11,"// волшебная рука",9288,null],[9298,"2026-05-27T19:52:53",56,"//давай",9296,null],[9299,"2026-05-27T19:53:11",56,"//люблю, когда игроки выкручиваются из ситуаций",1508,null],[9301,"2026-05-27T19:53:29",56,"//интересно",9292,null],[9302,"2026-05-27T19:53:53",5,"// почему персонажи ничего не говорят друг другу",1508,null],[9304,"2026-05-27T19:53:55",44,"//я мог бы дверь с петель снять , но понимаю что ты не дашь мне это сделать",9299,null],[9306,"2026-05-27T19:54:33",44,")) думают",9302,null],[9307,"2026-05-27T19:54:48",61,"— Пожалуй воздержусь",9293,null],[9308,"2026-05-27T19:55:22",61,"— И почему именно 224200?",1508,null],[9309,"2026-05-27T19:55:23",11,"— К'варсио, можешь поднести факел к голове дракона? \n// Могу попробовать анализ?\nВсе ещё интересна пара глаз",1508,null],[9311,"2026-05-27T19:55:29",56,"//хард, можешь им помочь, я не против)",1508,null],[9312,"2026-05-27T19:55:41",56,"//не кидай",9309,null],[9313,"2026-05-27T19:55:43",5,"*подношу факел*",1508,null],[9314,"2026-05-27T19:55:43",11,"// не надо нам помогать",9311,null],[9315,"2026-05-27T19:56:01",44,"// я думал что наш волшебник будет использовать волшебную руку , но ладно",9311,null],[9316,"2026-05-27T19:56:14",56,"* ты подносишь факел, однако ничего не происходит",1508,null],[9317,"2026-05-27T19:56:19",5,"— Я обдумал строки и сделал выводы. У тебя есть идеи лучше?",9308,null],[9318,"2026-05-27T19:56:22",11,"// зачем? Хотите методом тыка код найти?",1508,null],[9319,"2026-05-27T19:56:29",44,"// да",9318,null],[9320,"2026-05-27T19:57:01",11,"Акшиви использует волшебную руку и вводит код названный К'варсио",1508,null],[9322,"2026-05-27T19:57:20",44,"// ладно , если ты позвонишь сделать потом короткий отдых",9321,null],[9324,"2026-05-27T19:57:48",61,"— хмм",9317,null],[9325,"2026-05-27T19:58:16",56,"Хорошо, что ты использовал руку, иначе тебя бы быстро обожгло на месте\nВы видете, что на двери высветилось следующее\n*\n*\n*\n*\n*\n0",9320,null],[9326,"2026-05-27T19:58:51",56,"//да я шучу, делайте что в кайф",9322,null],[9327,"2026-05-27T19:58:52",5,"— Попытка не пытка. А попробуй 222200",1508,null],[9328,"2026-05-27T19:59:07",44,"// блин , значит я не буде получить боль",1508,null],[9329,"2026-05-27T19:59:09",11,"// Можно мне все же осмотреть голову?",1508,null],[9330,"2026-05-27T19:59:21",56,"Происходит тоже самое, ничего не изменилось",9327,null],[9331,"2026-05-27T20:00:16",44,"// а разхуярить , есть смысл ?\nЕсли что я сделаю преврку анали чтобы понять возможно его сломать или нет",9330,null],[9333,"2026-05-27T20:01:47",44,"// 4, 6, 2, ?,? 0 вот мой вариант",1508,null],[9334,"2026-05-27T20:01:57",56,"//хммм, можешь кинуть",9331,null],[9335,"2026-05-27T20:02:07",44,"/r 1d20-1",9331,null],[9337,"2026-05-27T20:02:23",44,"* ну если я не попробую то не узнаю *",9336,null],[9338,"2026-05-27T20:02:23",5,"Идеи лягушки всё не заканчивались.\n\n— 001180",1508,null],[9339,"2026-05-27T20:02:29",56,"*ты не понимаешь, как это сделать, по крайней мере сейчас",9336,null],[9340,"2026-05-27T20:03:09",56,"* деверь изменилась, там теперь видно*\n*\n*\n1\n*\n*\n0",9338,null],[9341,"2026-05-27T20:03:24",56,"// потом обьясню как шифровал)",1508,null],[9342,"2026-05-27T20:03:26",5,"Грунг начал понимать логику",1508,null],[9343,"2026-05-27T20:04:34",11,"// :( Смысла подносить факел к глазам дракона нет?",9341,null],[9344,"2026-05-27T20:04:43",56,"//Не-а, нет",9343,null],[9345,"2026-05-27T20:06:32",5,"— Ещё немного, и я разгадаю это! Как насчёт 661730?",1508,null],[9346,"2026-05-27T20:06:51",11,"*вздыхая использует руку*",1508,null],[9350,"2026-05-27T20:08:10",11,"// Могли бы мы попробовать станцевать у пары глаз дракона? На этом мои идеи заканчиваются",1508,null],[9351,"2026-05-27T20:08:20",56,"//мимо",9345,null],[9353,"2026-05-27T20:08:41",11,"// если бы Про был жив я могла бы станцевать под его игру",1508,null],[9354,"2026-05-27T20:09:25",11,"— 491520",1508,null],[9355,"2026-05-27T20:09:52",11,"— Шайло, твои идеи? — Она посмотрела на дварфа",1508,null],[9356,"2026-05-27T20:10:13",56,"**1520",9354,null],[9357,"2026-05-27T20:10:49",5,"— Ого",1508,null],[9359,"2026-05-27T20:10:59",44,"--- вообще нету  не каких идей",1508,null],[9360,"2026-05-27T20:11:21",5,"— Прогресс, может 811520",1508,null],[9361,"2026-05-27T20:11:57",56,"* дверь с огромным скрипом открывается, вы видете впереди тьму*\n//поздравляю",9360,null],[9362,"2026-05-27T20:12:07",56,"//объяснить ход мыслей?",1508,null],[9363,"2026-05-27T20:12:13",5,"*грунг обливается потом и вздыхает*",9361,null],[9364,"2026-05-27T20:12:21",5,"— у кого-нибудь есть вода?",1508,null],[9365,"2026-05-27T20:13:02",44,"// желательно да . хоть и велел логику, но не понимал",9362,null],[9366,"2026-05-27T20:13:13",61,"— Хорошая работа К'варсио\n\n*дает бурдюк с водой*",1508,null],[9367,"2026-05-27T20:13:15",11,"— Полагаю это можно назвать успехом. // Могу я осмотреться прежде чем войти?",9361,null],[9369,"2026-05-27T20:13:54",11,"Передразнивая: — \"Хорошая работа, К'варсио\"",9366,null],[9370,"2026-05-27T20:13:56",5,"— Спасибо!\n\n*берёт бурдюк и поливает себя водой*",9366,null],[9372,"2026-05-27T20:14:24",11,"Она закатила глаза и подлетела к открытой двери",9369,null],[9373,"2026-05-27T20:14:24",5,"*раздражённо квакает и делает жест ловли комара языком*",9369,null],[9374,"2026-05-27T20:14:51",56,"//\nПару глаз — 8 , если перевернуть, то будут похожи на 2 глаза\nПару ног — 11 , буквально похожи на ноги\nДва близнеца — изначально 69,но я решил оставить 52,так как они тоже похожи, если одну цифру перевернуть\nПустота — 0,думаю объяснять не надо",1508,null],[9375,"2026-05-27T20:14:54",11,"— Я так и знала что тебе нельзя доверять, лягушка \n*Прячется за дварфа*",1508,null],[9376,"2026-05-27T20:15:30",5,"*возвращает бурдюк и смотрит в проход*",1508,null],[9377,"2026-05-27T20:15:36",56,"//да",9367,null],[9378,"2026-05-27T20:15:40",11,"// вот близнецов мы не выкупили, сразу видно не астрологи персы😳",9374,null],[9379,"2026-05-27T20:16:00",61,"— Не стоит ругаться, друзья, мы все хорошо поработали, даже Шайло",1508,null],[9380,"2026-05-27T20:16:32",56,"//ну, изначально 69,тут очевидно наверное",9378,null],[9381,"2026-05-27T20:17:27",5,"Грунг кивком благодарит старца, и поднимает факел, готовясь войти",9379,null],[9382,"2026-05-27T20:17:30",11,"// анализ?",9377,null],[9383,"2026-05-27T20:17:46",56,"//кидай",9382,null],[9384,"2026-05-27T20:17:58",11,"/r d20+5",1508,null],[9386,"2026-05-27T20:18:10",5,"*вспомнив, что случилось с дварфом, жабка достаёт меч и перекладывает факел в левую руку*",1508,null],[9387,"2026-05-27T20:18:20",44,"// а мне единицы кормят  , а ему двадцатки",9385,null],[9388,"2026-05-27T20:18:45",11,"// мне феи подкрутили везение как для своего по блату",9387,null],[9389,"2026-05-27T20:19:13",56,"В приходе вы видите библиотеку — довольно большое здание, где видно огромное количество книг, многие из которых...... на полу? Однако это не следы драки, что-то более умиротворенное. Вы видите больше листков, написанных кровью и прожженных с обратной стороны. Вдалеке вы видите человека, который спит на полу, в окружении таких же книг и листочков.",1508,null],[9390,"2026-05-27T20:19:52",5,"Грунг поднимает факелы выше и всматривается в человека",1508,null],[9391,"2026-05-27T20:19:58",5,"// восприятие?",1508,null],[9392,"2026-05-27T20:20:05",44,"// на инециативу",9391,null],[9393,"2026-05-27T20:20:10",11,"— Этот человек живой? — Она летит в его сторону, но оглядывается на грунга с факелом прося о помощи взглядом",1508,null],[9394,"2026-05-27T20:20:29",5,"/r d20+2",1508,null],[9396,"2026-05-27T20:20:55",5,"// это шутка была?",9392,null],[9397,"2026-05-27T20:21:02",61,"— Думаете это он писал загадку?",1508,null],[9398,"2026-05-27T20:21:03",44,"// да",9396,null],[9399,"2026-05-27T20:21:08",5,"// пон",1508,null],[9400,"2026-05-27T20:22:07",5,"Увидев, что фея уже полетела, лягушка подходит к человеку и склоняется",9393,null],[9401,"2026-05-27T20:22:16",5,"освещая того факелом",1508,null],[9402,"2026-05-27T20:22:52",61,"// могу его проверить медициной?",1508,null],[9403,"2026-05-27T20:23:01",11,"Акши скептически смотрит на старика: — Зачем ему запирать себя здесь?",9397,null],[9404,"2026-05-27T20:23:10",11,"// кого мы видим?",9401,null],[9405,"2026-05-27T20:23:51",56,"Перед вами старик, на вид ему столько же лет, сколько и Ландеру. Вы видите довольно похожее телосложение, возможно, вы даже где-то его видели. Вы понимаете, что он спит; он пахнет пылью и тем самым запахом, который исходит от только что купленной книги. Его рука слегка исколота, откуда течёт небольшая, едва заметная струйка крови. Сам он выглядит довольно мудрым, но и растерянным человеком, с седыми волосами и бородой. \nТолько изредка видно, как его грудь поднимется то вверх, то вниз",1508,null],[9406,"2026-05-27T20:24:03",44,"* похожу к человеку который спит . И виду как все обеспокоены что человек может быть в мертвым *",1508,null],[9407,"2026-05-27T20:24:34",61,"— У него и спросим",9403,null],[9409,"2026-05-27T20:26:27",61,"* Виктор подошел к старику проверить все ли с ним впорядке*",1508,null],[9410,"2026-05-27T20:26:32",11,"— Что-ж, он живой, похоже даже почти не ранен. Эта одежда выглядит знакомо пусть и более старой, но такая же одежда была у молодого юноши фотографию которого показывал господин Ландер. Может ли это быть он?",9405,null],[9411,"2026-05-27T20:27:15",5,"— Я узнаю эту шкуру. Думаю, это он",1508,null],[9412,"2026-05-27T20:27:18",11,"— Можем ли мы привести его в чувство?",1508,null],[9413,"2026-05-27T20:27:20",44,"* я осматриваю этого мужчину и вспомнил что этот тот чел с потрето *\n--- походу это он . Давай его разбудим ?",1508,null],[9415,"2026-05-27T20:27:55",5,"Грунг квакает во весь голос и смотрит на реакцию человека",1508,null],[9416,"2026-05-27T20:28:12",61,"— Да, это он и кажется в относительном порядке",1508,null],[9417,"2026-05-27T20:28:41",11,"Акшиви опускается на пол, и чихнув из-за пыли в библиотеке рассматривает листы вокруг старика",1508,null],[9418,"2026-05-27T20:28:47",11,"// Его работы?",1508,null],[9419,"2026-05-27T20:29:56",56,"//очень вероятно",1508,null],[9420,"2026-05-27T20:30:00",61,"*Друид легко трогает человека за плечо*\n\n— Просыпайтесь, господин поэт",1508,null],[9421,"2026-05-27T20:30:09",56,"/r d20+4",1508,null],[9424,"2026-05-27T20:30:35",56,"//Кд?",9417,null],[9425,"2026-05-27T20:31:00",11,"// 11* сори я додик х2",1508,null],[9427,"2026-05-27T20:31:54",61,"// от чего 4?",9421,null],[9428,"2026-05-27T20:32:05",56,"//сила)",9427,null],[9429,"2026-05-27T20:39:28",56,"Его глаза постепенно открываются; видя новые лица, он приходит в некоторое смятение. Но как только он просыпается окончательно, в того, кто посмел тронуть его работы без разрешения, летит кулак прямо в лицо.\n\n— Прошу учитывать чужой труд, букашка! И трогать его тебе или нет должен решать владелец, а не ты, понятно?\n\nПосле этого он поворачивается к вам и начинает вставать.\n\n— Непростительно, чтобы вы, священники мои, посмели так со мной обращаться! Непростительно! Вы должны быть счастливы такой возможности и такому стечению обстоятельств, должны благодарить судьбу за то, что удалось меня поймать. Ибо будь я не человеком — мигом бы вас, букашек, что даже не знают воли своего обожателя, прибил, не сомневайтесь!\n\nОн начинает яростно на вас смотреть, видимо, готовясь отбиваться дальше. Ещё бы чуть-чуть и кажется, из его рта пошёл пар.",9425,null],[9430,"2026-05-27T20:41:43",5,"//реакция стража\nК'Варсио молниеносно приставляет меч к горлу старца и толкает его к стене",1508,null],[9431,"2026-05-27T20:42:24",56,"//атлетика",1508,null],[9432,"2026-05-27T20:42:36",5,"/r d20+5",1508,null],[9434,"2026-05-27T20:42:41",44,"// давай мы его от пиздим , гули он тако агрессивный ?",9429,null],[9435,"2026-05-27T20:42:53",11,"// ??",1508,null],[9437,"2026-05-27T20:43:07",56,"//у тебя это получается",9430,null],[9438,"2026-05-27T20:43:11",11,"// я просто не понимаю что с моим персом",1508,null],[9439,"2026-05-27T20:44:09",5,"— А ну-ка успокойся, старик!",1508,null],[9440,"2026-05-27T20:44:19",5,"— Ква!",1508,null],[9441,"2026-05-27T20:46:09",61,"— Пожалуйста, не стоит злиться, мы не хотим причинить вам вреда",1508,null],[9442,"2026-05-27T20:50:01",44,"* ага про анализируем ситуация. Чел ударил фею. Лягушка , направило своё орудие , Виктор корнеплод, хочет успокоить всех , а кобальт , а где он ? , . *",1508,null],[9443,"2026-05-27T20:53:33",56,"Холодная сталь касается его горла,меч едва заметно дрожит, то ли от твоего гнева, то ли от его судорожных движений. Он начинает шипеть в твою сторону, пар вытекает у него изо рта тонкими струйками. Он кряхтит, пытаясь выбраться, плечи ходят ходуном, однако у него это получается с огромным трудом. Его тело больше не слушается, как прежде.\n\n— Я говорил вам сотни раз и буду повторять столько, сколько потребуется. Одрициуса нет! \n\n голос срывается почти на визг. \n— Он погиб там! Остался только Одри — поэт с великим будущим, такова моя цель. Я не буду больше гнить здесь.\n\nОн обводит вас лихорадочным взглядом, в глазах — ни капли раскаяния, только загнанная, отчаянная решимость.\n\n— Раньше я «защищал» эти земли, сидел тут без какой-либо нужды, пока другие творили, писали и делали, что им в голову вздумается. А вы боитесь потерять своего идола — смысл жизни, который угас, как только я стал им. \n Он сглатывает, горло судорожно дергается, почти касаясь лезвия, кажется начала течь ещё одна струйка крови. \n— Дайте уйти, дайте дожить остаток дней там, где меня ждут! Я не ваша марионетка, не ваша статуя для обожания. Я. Теперь! Человек!\n\nОн рычит последние фразы, брызжет слюной, с каждым разом всё интенсивнее, пока голос не превращается в грубый, надсадный хрип — будто после долгого удушья. В наступившей тишине слышно только его тяжёлое, со свистом, дыхание.",1508,null],[9444,"2026-05-27T20:54:51",5,"— Похоже, у него серьёзный внутренний конфликт",1508,null],[9445,"2026-05-27T20:55:27",44,"// шизофрения",9444,null],[9446,"2026-05-27T20:56:11",5,"// разговаривай персом",1508,null],[9447,"2026-05-27T20:56:55",44,"// зануда",9446,null],[9448,"2026-05-27T20:57:17",11,"// Прости, я не понимаю что с моим персом так что не знаю как реагировать",1508,null],[9449,"2026-05-27T20:57:44",44,"// любом случае ты живой , так что ты можешь участвовать",9448,null],[9450,"2026-05-27T21:00:23",61,"*Лицо Виктора нахмурилось*\n\n— О чем вы говорите?",1508,null],[9451,"2026-05-27T21:02:31",44,"// можно у точнее? просто для меня не понятно , типа у него раздвоение личностей?",9443,null],[9452,"2026-05-27T21:03:13",56,"//дам подсказку с проверкой истории",9451,null],[9453,"2026-05-27T21:03:19",5,"// проясни ситуацию с феей пожалуйста",1508,null],[9455,"2026-05-27T21:03:56",44,"/r 1d20-1",9452,null],[9457,"2026-05-27T21:04:02",11,"// Ты так и не озвучил попал он или нет? Если да то сколько урона. Извини, мне неловко это третий раз спрашивать",1508,null],[9458,"2026-05-27T21:04:26",56,"* с феей всё в порядке, однако ей нанеслось 2 урона*",9453,null],[9459,"2026-05-27T21:04:42",56,"//извини, моя вина, он попал",9457,null],[9460,"2026-05-27T21:05:35",56,"* Имя \"Одрициус\" Кажется знакомым, кажется так звали дракона, что здесь обитал. *",9455,null],[9461,"2026-05-27T21:07:13",5,"Увидев взгляд старика, грунг опускает меч и отходит",1508,null],[9463,"2026-05-27T21:08:02",11,"— Кажется я в один момент потеряла интерес к поэзии на всю жизнь.. — Поднимаясь с пола произнесла Акши — Старик, мы пришли по просьбе твоего старого знакомого, а ты так встречаешь гостей?",1508,null],[9464,"2026-05-27T21:09:41",56,"//убеждение, ему щас не до фраз",9463,null],[9465,"2026-05-27T21:10:19",11,"/r d20+1",1508,null],[9467,"2026-05-27T21:10:36",56,"//позволяю помочь",1508,null],[9468,"2026-05-27T21:11:41",11,"— И костей дракона мне не видать — тихо произнесла она сама для себя",1508,null],[9469,"2026-05-27T21:12:36",56,"//понял, никто не поможет",1508,null],[9470,"2026-05-27T21:12:49",5,"// с чем поможет?",1508,null],[9471,"2026-05-27T21:12:51",5,"// кому",1508,null],[9472,"2026-05-27T21:12:55",44,"// ща пишу",9469,null],[9473,"2026-05-27T21:12:55",11,"// Они не знают что подразумевается под помощью в этой ситуации",1508,null],[9474,"2026-05-27T21:13:09",56,"//раздвоения личности нет, в нём нет демона",9455,null],[9475,"2026-05-27T21:13:09",61,"// да",1508,null],[9477,"2026-05-27T21:16:22",44,"* я отпускаю мечь лягушка , чтобы уменьшить давление в разговоре.* \n--- Мы пришли сюда по просьбе одного человека, а если точнее -жреца по имени Ландо Доэ. Он за вас беспокоится и отправил нас, чтобы найти вас. Пожалуйста, пройдите с нами, чтобы он мог убедиться, что вы в безопасности",1508,null],[9478,"2026-05-27T21:17:00",44,"// я лучше не придумал , простите",9477,null],[9479,"2026-05-27T21:19:41",5,"*наблюдает за ситуацией, не зная что делать дальше*",1508,null],[9482,"2026-05-27T21:29:05",56,"Как только меч опускается, он тут же опирается рукой о пол и начинает откашливаться, делая тяжёлые, рваные вдохи и выдохи. Постепенно дыхание выравнивается. Он приходит в себя.\n\n— Ландер…\n голос звучит тихо, почти устало. \n— Вы пришли с ним?\n\nОн успокаивается, поднимает голову и смотрит на вас спокойным, даже умиротворённым взглядом ,ни следа недавней ярости.\n\n— Прошу простить меня за мои выходки, букашки. Я подумал, что вы — одни из приспешников культа Дракона. \n Он потирает горло. \n— Но, видимо, они так и не посмели убрать моё послание. Как я и предполагал раньше, они не тронут ничего из того, что принадлежит мне.\n\nЕго лицо, до этого напряжённое и бледное, вдруг преображается в улыбку, на удивление тёплую. \n\n— Значит, и с культистами тоже окончено. Вся память почитания Одрициуса разрушена. \n Он с облегчением выдыхает. \n— Как же я рад этому. Благодарю вас, букашки.\n\nОн поднимается, слегка пошатываясь, и начинает собирать свои листки. Затем берёт небольшое перо с острым наконечником, до краёв заполненное жидкостью багрового оттенка, и бережно прячет его в складках шкуры.\n\n— Думаю, нам стоит идти на волю. Опасности больше нет.",1508,null],[9483,"2026-05-27T21:29:12",56,"//я писал(",1508,null],[9484,"2026-05-27T21:30:56",5,"— Знаете, я очень интересуюсь новыми знаниями. Можно мне взять какую-нибудь интересную книги, или, возможно, магический свиток?",1508,null],[9485,"2026-05-27T21:31:03",5,"// убеждение?",1508,null],[9486,"2026-05-27T21:31:13",11,"// наглость второе счастье",1508,null],[9487,"2026-05-27T21:31:47",11,"*С интересом, но опаской оглядывается в полумраке на книги после слов грунга*",1508,null],[9488,"2026-05-27T21:32:26",44,"* культистов ,культ  драконы , нет , я даже не хочу связываться в это дерьмо * \n--- ладно , пойдем по скорое пока не стемнело.",9482,null],[9489,"2026-05-27T21:32:55",56,"//ой как сомневаюсь",9485,null],[9490,"2026-05-27T21:33:06",61,"— Идем, господин поэт, вас ждет ваш друг, вы ему расскажите все что произошло за эти годы",1508,null],[9491,"2026-05-27T21:33:15",5,"//  он же благодарен(",1508,null],[9492,"2026-05-27T21:33:33",56,"//попробуй",9491,null],[9493,"2026-05-27T21:33:36",11,"// тоже хочешь кулаком получить?",1508,null],[9494,"2026-05-27T21:33:42",5,"/r d20-1",1508,null],[9496,"2026-05-27T21:33:54",56,"//пзда",1508,null],[9497,"2026-05-27T21:33:56",11,"// охох",1508,null],[9498,"2026-05-27T21:33:59",5,"// ахвпхап",1508,null],[9499,"2026-05-27T21:34:14",44,"// жаль что навыки не критуют в днд 5е",9495,null],[9503,"2026-05-27T21:40:55",5,"// жду своей судьбы",1508,null],[9504,"2026-05-27T21:46:30",56,"— Так уж и быть, букашка, можешь взять. Но только в этот раз.\n\nОн достаёт и протягивает тебе свиток.\n\n— Держи, я вложил в него магию. Используй с умом.\n\n[Получай предмет: Свиток доспеха мага]\n\n---\n\nВнезапно из коридора, откуда вы пришли, раздаются шаги  тяжёлые, уверенные а следом мужской голос, гулкий и полный подобострастия:\n\n— Господин Одрициус! Мы вернулись. Один невежественный человек посмел ходить по вашим землям — мы избавились от него. Прошу, учтите наши усилия! Мы клянёмся, что больше никто не посмеет приблизиться к вам. Те, кто превратил вас в человека, поплатятся, обещаем!\n\nОдри вздрагивает. Резко поворачивается к вам, и в его глазах — тревога, почти паника. Этого он точно не ожидал.\n\nКультисты вернулись. А значит, времени почти не осталось.",9484,null],[9505,"2026-05-27T21:46:58",5,"— Спасибо!\n\nЖабка поклонилась",9504,null],[9506,"2026-05-27T21:48:13",5,"// а можно факел повесить куда-то?",1508,null],[9507,"2026-05-27T21:48:32",56,"//по сути можно",9506,null],[9508,"2026-05-27T21:49:08",5,"Грунг осторожно ставит факел на одно из креплений у стены и достаёт второй меч",1508,null],[9509,"2026-05-27T21:49:29",11,"Фея вздрогнула от слов про человека от которого избавились",9504,null],[9510,"2026-05-27T21:49:42",11,"— Боюсь нам больше некуда спешить..",1508,null],[9511,"2026-05-27T21:50:18",5,"Затем к'Варсио  выходит вперёд, становясь около дверного прохода. Но не занимая его целиком, чтобы осталось место для дварфа",1508,null],[9512,"2026-05-27T21:50:29",61,"Виктор, понимая что произошло, достает оружие",1508,null],[9513,"2026-05-27T21:51:43",11,"// Коля был прав масло могло пригодиться",1508,null],[9514,"2026-05-27T21:52:02",5,"Лягушка обращается к старцу: \n— Не волнуйтесь, мы разберемся. Держитесь за нами",1508,null],[9515,"2026-05-27T21:52:17",44,"* я понимаю что мне больше не кто не заплатить иза культистов , так что пусть они заплатят за него , своей кровью* .* Достаю двуручный мечь *",9512,null],[9516,"2026-05-27T21:52:26",5,"— Стоит ли нам устроить засаду?",1508,null],[9517,"2026-05-27T21:52:52",44,"// да , я бы все равно купил , рано или поздно приходится",9513,null],[9518,"2026-05-27T21:54:29",56,"//каков ваш план?",1508,null],[9519,"2026-05-27T21:54:59",44,"// убить всёх",9518,null],[9520,"2026-05-27T21:55:06",11,"// Они знают что мы тут?",1508,null],[9521,"2026-05-27T21:55:29",56,"//сомневаюсь",9520,null],[9522,"2026-05-27T21:56:08",5,"— Нам стоит укрыться прямо за входом, чтобы внезапно напасть, когда они войдут",1508,null],[9523,"2026-05-27T21:56:58",11,"*Прячется на одной из полок подальше от входа*",1508,null],[9524,"2026-05-27T21:57:24",5,"*гашу факел*",1508,null],[9525,"2026-05-27T21:57:44",44,"-- как хотите я не буду прятаться. Я буду ждать их у входа",9522,null],[9527,"2026-05-27T21:58:06",11,"// не туда 🫪",1508,null],[9528,"2026-05-27T21:58:17",5,"— Ну и дурак!\n\nГрунг старается говорить тихо, но квакает от возмущения",9525,null],[9529,"2026-05-27T21:58:32",61,"Виктор берет рядом лежащий камень и прячется позади стола",9522,null],[9530,"2026-05-27T21:58:38",56,"//итак, паладин остаётся на месте, остальные в засаде, верно?",1508,null],[9531,"2026-05-27T21:59:01",5,"да",1508,null],[9532,"2026-05-27T21:59:11",44,"// да , я что трус чтобы прятаться? Я лучше умру",9530,null],[9533,"2026-05-27T21:59:14",5,"однако я рядом с паладином, но за входом",1508,null],[9534,"2026-05-27T21:59:14",11,"// А мы вообще преимущество от засады какое-то получаем? У нас ведь нет плута там",1508,null],[9535,"2026-05-27T21:59:49",56,"//Думаю да",9534,null],[9536,"2026-05-27T22:00:39",5,"// готов",1508,null],[9537,"2026-05-27T22:00:51",44,"// Да , а именно  у вас будет 1 ход бесплатный и вродебы преймучества на попадание",9534,null],[9540,"2026-05-27T22:02:38",11,"// окей тогда мы готовы",1508,null],[9545,"2026-05-27T22:04:10",11,"// Грунг потушил факел и ни у кого тут нету ночного зрения, я хочу использовать огонь(сияние) фей что бы не драться в полной темноте",1508,null],[9547,"2026-05-27T22:04:38",5,"// враги будут нашими светильниками",1508,null],[9551,"2026-05-27T22:05:28",5,"// бой?",1508,null],[9556,"2026-05-27T22:07:33",56,"Дверь распахивается. В комнату входят трое: двое стражей в тяжёлых доспехах и один — в центре, выше остальных, в светлых одеяниях с символикой дракона. Его облачение выдаёт в нём диакона культа, того, кто имеет власть.\n\nУвидев тебя, паладина, он замирает на мгновение. В глазах мелькает удивление, почти оскорбление. Два стражника без команды вскидывают оружие, нацелив его прямо на тебя.\n\n— Ты… \nголос диакона дрожит от праведного гнева.\n — Ты посмел потревожить покои самого Дракона! Как смеешь ты так низко пасть?! Я не позволю тебе осквернять господина Одрициуса, пусть даже он сейчас в ином обличии!\n\nОдри стоит в стороне. Его кулаки сжаты до побелевших костяшек, зубы стиснуты так, что на скулах вздуваются желваки. Злоба, долго копившаяся, теперь рвётся наружу.\n\n— Ты… не позволишь? \nего голос срывается на рычание.\n — Не тебе решать за меня, червь! Я не позволю тебе управлять мной! Таков мой вердикт!\n\nОн делает шаг вперёд, вставая плечом к плечу с тобой. Из его груди вырывается горячий пар, словно внутри пробуждается нечто древнее\n\n— Я тоже буду сражаться!",1508,null],[9558,"2026-05-27T22:07:50",56,"//инициатива",1508,null],[9561,"2026-05-27T22:08:51",44,"/r 1d20-1",9558,null],[9564,"2026-05-27T22:09:28",44,"// еблатские рак кубов . Ладно , нужно спомнить свою цитату , верь в себя что ты везучий",9562,null],[9566,"2026-05-27T22:09:40",56,"/r d20 стражник 1\n/r d20 стражник 2\n/r d20+2 священник \n/r d20+2 Одри",1508,null],[9568,"2026-05-27T22:09:51",5,"// всем инициативу?",1508,null],[9569,"2026-05-27T22:09:59",56,"//Агась",9568,null],[9570,"2026-05-27T22:10:24",5,"/r d20+2",1508,null],[9572,"2026-05-27T22:10:26",56,"/r d20 стражник один\n/r d20 стражник два\n/r d20+2 священник \n/r d20+2 Одри",1508,null],[9574,"2026-05-27T22:10:32",44,"// а да я в ахуе что меня знаю другие паладини , у меня также свечного символа нету и вообще я даже в церкви не разу не был",9556,null],[9575,"2026-05-27T22:10:57",5,"// а как они что-то видят в темноте?",9556,null],[9576,"2026-05-27T22:11:01",11,"/r d20+1",1508,null],[9578,"2026-05-27T22:11:02",56,"//прости, ошибся, могу исправить",9574,null],[9579,"2026-05-27T22:11:24",61,"/r d20+1",1508,null],[9581,"2026-05-27T22:11:28",56,"//у священника свет",9575,null],[9583,"2026-05-27T22:11:49",5,"// у диакона или одри?",9581,null],[9585,"2026-05-27T22:12:05",56,"// у диакона",9583,null],[9589,"2026-05-27T22:12:40",44,"// как хочешь. Но если говорить просто, я продал душу, чтобы получить демоническую силу. Мой покровитель не любит, когда всякие исчадия бродят по Материальному плану, и просит, чтобы я их убивал. Возможно, именно из-за этого они меня и узнали",9578,null],[9591,"2026-05-27T22:12:49",5,"// а почему 2 раза бросок?",9573,null],[9594,"2026-05-27T22:13:20",56,"Я просто ошибся с цифрами",9591,null],[9598,"2026-05-27T22:13:37",56,"//их нельзя упоминать, когда кидаешь, вот и перебросил",1508,null],[9599,"2026-05-27T22:13:45",5,"// понял",1508,null],[9601,"2026-05-27T22:13:50",56,"//только из-за этого, чтобы не путаться",1508,null],[9604,"2026-05-27T22:14:13",11,"// Ну нам в очередной раз \"везёт\"",1508,null],[9607,"2026-05-27T22:15:05",44,"// а да , вы сделали проверку скрытности когда вы делали засаду?",1508,null],[9610,"2026-05-27T22:15:29",56,"Инициатива:\n17 Одри\n14 стражник 1\n13 стражник 2\n11 Дьякон \n10 корнеплод\n паладин кд 16\n3 Фея 11\n3 грунг 16",1508,null],[9611,"2026-05-27T22:15:29",5,"// так нас не видели враждебные существа. Автомат успех же",1508,null],[9613,"2026-05-27T22:16:05",44,"Пожалуйста убери цифры 4 , это к несчастью",9610,null],[9616,"2026-05-27T22:16:37",11,"// Миста разлогинься",9613,null],[9617,"2026-05-27T22:16:37",44,"// я не шучу, как по твоему у меня 2 разу подарят критическая не удача",9613,null],[9618,"2026-05-27T22:16:50",56,"/r d20+4\n/r d20+4",1508,null],[9620,"2026-05-27T22:17:04",56,"//Кд?",9617,null],[9622,"2026-05-27T22:17:36",44,"//16 ,  чтобы всякий раз не писать сколкьо у меня КД то напиши в инициативе. И да убери 4",9620,null],[9624,"2026-05-27T22:18:07",44,"// душа довольна",9610,null],[9627,"2026-05-27T22:18:35",56,"//Для тебя убрал, китаеныш мой любимый\n会说汉语吗？",9622,null],[9630,"2026-05-27T22:18:59",5,"//моё 16",9620,null],[9631,"2026-05-27T22:19:02",44,"// я по китайский не говорю , наверно что-то там приятное",9624,null],[9632,"2026-05-27T22:19:02",11,"//11",9620,null],[9636,"2026-05-27T22:19:57",44,"// а точно у меня нету души , хохохох",9624,null],[9637,"2026-05-27T22:19:58",61,"//13",1508,null],[9642,"2026-05-27T22:20:48",5,"// одри тащи",1508,null],[9661,"2026-05-27T22:23:52",5,"// всё, больше 1 не будет",1508,null],[9665,"2026-05-27T22:24:32",44,"// а да это по кому  и на что ?",9619,null],[9671,"2026-05-27T22:26:13",5,"// атака одри и чей-то спасбросок?",9665,null],[9673,"2026-05-27T22:26:38",44,"// а разве сам Одри не должна кинуть?",9671,null],[9675,"2026-05-27T22:26:53",44,"/ @Psinablohastay делает жесткое описание как два стражника нас тарабонят .",9674,null],[9677,"2026-05-27T22:27:17",11,"// сперва тебя, а мы смотрим (виновата наша инициатива)",1508,null],[9678,"2026-05-27T22:27:28",11,"// приобретен подкласс старого повара",1508,null],[9679,"2026-05-27T22:27:33",56,"Одри взмахивает пером — наконечник оставляет в воздухе багровые штрихи, и они не гаснут, а начинают пульсировать, складываясь в светящиеся руны. Он чертит их быстро, почти яростно, и с каждым движением воздух вокруг вас теплеет.\n\n— Вперёд! Ибо вы все здесь погибнете! — голос его звенит, но не от страха, а от древней, пробуждающейся силы.\n\nВнезапно вас окутывает тепло — мягкое, обволакивающее, словно утреннее солнце ласкает кожу после долгой ночи. Усталость отступает, раны будто перестают ныть, сердце бьётся ровнее и увереннее.\n\n[Эффект: Героизм. Максимальное HP увеличено на 5]\n\n— Продолжай сиять, воин! — Одри смотрит на тебя, и в его глазах — не прежняя затравленность, а искренняя, почти восторженная вера. — Так же, как ты засиял в моих глазах. Такова твоя судьба — неси моё пламя!\n\n[ @Az095as0 получает Бардовское вдохновение]\n\n---\n\nТем временем два стражника бросаются на паладина одновременно. Первый клинок ты встречаешь своим — сталь ударяется о сталь, и на мгновение помещение озаряется снопом ярких искр, выхватывающих из темноты искажённые злобой лица.\n\nНо второй стражник уже заходит сбоку. Его меч прорезает воздух и достигает цели — броня пробита, лезвие входит в бок. Однако твоя кровь, горячая, почти кипящая, будто сама восстаёт против вторжения: она густеет, обволакивает клинок и не даёт ему погрузиться глубже. Ты чувствуешь, как сталь упирается в невидимую преграду внутри тебя.\n\nДиакон тем временем отступает за спины своих прислужников. Он не сводит с тебя глаз, пальцы нервно теребят край одеяния. Видно — он готовится уклоняться, знает, что твой удар может последовать в любой миг.\n\n[Статус противника: Уклонение — готовится избежать твоей атаки]",1508,null],[9680,"2026-05-27T22:28:01",56,"/r d8+2",1508,null],[9682,"2026-05-27T22:28:11",56,"//наноси 4 урона",1508,null],[9686,"2026-05-27T22:28:28",5,"/героизм на всех нас?",9679,null],[9689,"2026-05-27T22:28:36",56,"//верно",9686,null],[9694,"2026-05-27T22:29:18",56,"@landihus твой ход",1508,null],[9697,"2026-05-27T22:29:33",5,"// у меня реакция!",1508,null],[9701,"2026-05-27T22:29:40",5,"на атаку по паладину",1508,null],[9702,"2026-05-27T22:29:45",56,"//ебашь",9697,null],[9717,"2026-05-27T22:31:15",5,"Грунг встаёт в полный рост, проводит лезвием меча по своей лапе и наносит удар по первому стражнику, атаковавшему паладина",1508,null],[9720,"2026-05-27T22:31:26",5,"// преимущество за скрытность?",1508,null],[9728,"2026-05-27T22:32:09",56,"//он использовал уклонение, следовательно нет",9720,null],[9729,"2026-05-27T22:32:21",5,"// это диакон",9728,null],[9730,"2026-05-27T22:32:26",5,"// я стражника бью",1508,null],[9732,"2026-05-27T22:32:32",56,"//а, тогда да",1508,null],[9735,"2026-05-27T22:32:53",5,"/r +d20+5",1508,null],[9745,"2026-05-27T22:33:38",5,"// урон",1508,null],[9748,"2026-05-27T22:33:53",5,"/r d6+3",1508,null],[9753,"2026-05-27T22:34:19",5,"// стражник должен против яда бросить",1508,null],[9754,"2026-05-27T22:34:23",5,"// там сл 12",1508,null],[9757,"2026-05-27T22:34:38",5,"//телосложение",1508,null],[9759,"2026-05-27T22:34:54",56,"/r d20+4 спас тела",1508,null],[9763,"2026-05-27T22:35:04",5,"// урон яда",1508,null],[9764,"2026-05-27T22:35:04",56,"//ебашь двойной урон",1508,null],[9765,"2026-05-27T22:35:14",5,"/r 2d4",1508,null],[9770,"2026-05-27T22:35:32",5,"// всм двойной?",9764,null],[9772,"2026-05-27T22:35:48",56,"//у него Крит единица, я вас пощажу",9770,null],[9773,"2026-05-27T22:35:54",44,"// спаспроски тоже не могут критиковать",9764,null],[9774,"2026-05-27T22:36:04",5,"// типа урон яда удвоился?",1508,null],[9775,"2026-05-27T22:36:09",5,"/r 2d4",1508,null],[9780,"2026-05-27T22:37:09",5,"// что-то ещё?",1508,null],[9783,"2026-05-27T22:37:18",56,"//да я знаю, просто решил так сделать)",9773,null],[9786,"2026-05-27T22:37:25",56,"//достаточно",9780,null],[9788,"2026-05-27T22:37:36",44,"// ну ладно.",9783,null],[9789,"2026-05-27T22:37:41",56,"//в кого кидаешь камень, корнеплод?",1508,null],[9799,"2026-05-27T22:38:39",61,"Виктор бросает камень в того же стражника, которого бил жаб",1508,null],[9803,"2026-05-27T22:39:07",61,"/r +d20+3",1508,null],[9805,"2026-05-27T22:39:07",56,"//кидай",1508,null],[9809,"2026-05-27T22:40:00",11,"// говорю же мы везучие",9804,null],[9811,"2026-05-27T22:40:14",61,"// я не попал типа?",1508,null],[9816,"2026-05-27T22:40:34",56,"//Не-а",9811,null],[9821,"2026-05-27T22:41:21",5,"// надо было мороженую картошку кидать",1508,null],[9823,"2026-05-27T22:41:35",56,"*стражника сильно скрутило от твоего яда, он точно не был к этому готов, однако к броску камня он был готов и смог отбить его щитом*",1508,null],[9825,"2026-05-27T22:41:46",56,"@Az095as0 ход",1508,null],[9826,"2026-05-27T22:42:06",44,"// как я понимаю стражники меня окружили ?",9825,null],[9830,"2026-05-27T22:42:21",5,"// тут есть механика?",1508,null],[9839,"2026-05-27T22:43:01",56,"//не, давайте без окружения",9826,null],[9840,"2026-05-27T22:43:03",44,"// да , есть ты кого-то окружил , отпусти ты и твой союзник окружили врага , то вы оба бьёт с преимуществом",9830,null],[9843,"2026-05-27T22:43:12",56,"//в тестовой за этим трудно следить",1508,null],[9845,"2026-05-27T22:43:21",56,"//или можем считатт",1508,null],[9846,"2026-05-27T22:43:26",56,"//как хотите?",1508,null],[9847,"2026-05-27T22:43:28",44,"// как сложно без карты . Я бы сделал бы как-то карту хоть на тетрадке",9839,null],[9851,"2026-05-27T22:43:42",11,"// Ну мы новички так что я не против упрощения, но пускай Коля решает",1508,null],[9854,"2026-05-27T22:43:57",44,"// а вы новичка ладно тогда.",9851,null],[9855,"2026-05-27T22:44:10",44,"// а насколько от меня далеко свеченик?",1508,null],[9859,"2026-05-27T22:44:28",56,"//футов 20",1508,null],[9865,"2026-05-27T22:45:33",5,"// без окружения?",9854,null],[9871,"2026-05-27T22:46:03",44,"// блин значит не смогу срузуже по троим . Ладно , тогда ( забыл как называется боевой прием на двуручный мечь .)\n* Я крепко держу свой двуручный мечь и делаю движение подобному вихрю , чтобы попасть по всем стражам *",9859,null],[9872,"2026-05-27T22:46:10",44,"/r 1d20+5",9871,null],[9877,"2026-05-27T22:46:40",44,"/r 2d20+5",1508,null],[9880,"2026-05-27T22:47:02",56,"// а почему?",9877,null],[9882,"2026-05-27T22:47:04",44,"// а какое у нас бардовской дерзновение ?",9878,null],[9883,"2026-05-27T22:47:10",44,"// это помеха",9880,null],[9884,"2026-05-27T22:47:16",56,"//к6",1508,null],[9889,"2026-05-27T22:47:53",44,"// я могу использовать только о один раз ? ( Просто не понимаю что делает )",9884,null],[9900,"2026-05-27T22:48:42",56,"//да, один раз к броску можешь докинуть к6",9889,null],[9902,"2026-05-27T22:48:50",44,"// использую бардовской дерзновение к значение к 7",9878,null],[9904,"2026-05-27T22:48:57",44,"/r 1d6",9902,null],[9910,"2026-05-27T22:49:19",44,"7+5+6=18 другое дело //",9905,null],[9915,"2026-05-27T22:49:50",56,"//урон",1508,null],[9916,"2026-05-27T22:50:00",44,"/r 1d6+3",9915,null],[9926,"2026-05-27T22:51:02",44,"//Господа, на этом все .",9918,null],[9930,"2026-05-27T22:51:17",5,"// это урон или что такое?",9877,null],[9933,"2026-05-27T22:51:21",56,"//ты добил, поздравляю",1508,null],[9936,"2026-05-27T22:51:36",44,"// фаталити можно ?",9933,null],[9942,"2026-05-27T22:52:14",56,"//ебашь",9936,null],[9987,"2026-05-27T22:57:16",44,"* Когда я закружилась в вихревой атаке, моё лезвие с глухим треском врубилось в плоть одного из уродливых стражников. Не дав ему опомниться, я намертво вцепилась свободной рукой в его горло, заглушая предсмертный хрип. Рывком вогнав свой тяжеленный двуручник глубоко ему в живот, я с дикой яростью проворачивала и рвала лезвие внутри, расширяя рану до тех пор, пока наружу не хлынула кровь, а на землю с влажным шлепком не вывалились его склизкие кишки.*\n\nСтил B\n\nКомбо \nДобивание 1\nSuperkill 6 \nЖестокость 3",9942,null],[9988,"2026-05-27T22:57:16",5,"// я так понял, это проверки попадания отдельно для 2 стражников? а что тогда первый д20 было",9873,null],[9994,"2026-05-27T22:58:18",56,"//Агась",9988,null],[9999,"2026-05-27T22:58:50",56,"//next",1508,null],[10004,"2026-05-27T22:59:19",11,"//я?",1508,null],[10007,"2026-05-27T23:00:36",5,"// объясните пж, на что первый бросок был",9873,null],[10008,"2026-05-27T23:01:09",56,"//Агась",10004,null],[10009,"2026-05-27T23:01:31",56,"//он кинул, чтобы прожить двух стражников, приём двуручного меча",10007,null],[10015,"2026-05-27T23:02:35",5,"// а второй 2д20?",10009,null],[10016,"2026-05-27T23:02:49",44,"// я хз как кидать помеху на этом боте",10015,null],[10020,"2026-05-27T23:03:26",5,"// а почему вторая атака с помехой? по диакону что ли?",1508,null],[10022,"2026-05-27T23:03:37",56,"/r -d20",10016,null],[10024,"2026-05-27T23:03:38",11,"Фокус на шее феи засветился \n*использую волшебную стрелу* \n// Я могу распределить три заряда на двоих?",1508,null],[10029,"2026-05-27T23:03:57",56,"//да, можешь",10024,null],[10032,"2026-05-27T23:04:26",11,"Тогда два заряда в стражника и один в Диакона \n// У меня будет преимущество по кому-то?",1508,null],[10035,"2026-05-27T23:05:00",44,"// потому что одни или второй стражни использовал действие у ворот , оно даёт помеху на атаку и вродебы преймучества на спросов ловкость",10020,null],[10042,"2026-05-27T23:05:29",56,"// не нужно кидать, это волшебные стрелы",10032,null],[10043,"2026-05-27T23:05:31",5,"// стражники атаковали, диакон стоял в уклонении",10035,null],[10054,"2026-05-27T23:06:33",11,"/r 2d4+1\n/r d4+1",1508,null],[10063,"2026-05-27T23:07:32",44,"// что тоетсь не один стражник не использовал уклонение?",10043,null],[10066,"2026-05-27T23:07:54",56,"//не-а",1508,null],[10067,"2026-05-27T23:08:07",44,"// @Psinablohastay что ты не сказ , тогда я вообще по приколу кидал  с помехой",10063,null],[10069,"2026-05-27T23:08:14",5,"// прикольчики",1508,null],[10071,"2026-05-27T23:08:23",5,"// мой ход?",1508,null],[10076,"2026-05-27T23:08:52",56,"//да",10071,null],[10082,"2026-05-27T23:09:12",56,"//прости(\nБошка плохо варит, 4 часа ночи)",10067,null],[10084,"2026-05-27T23:09:16",44,"// ну все равно первый бросок бы не попал ,",10082,null],[10089,"2026-05-27T23:09:43",5,"Грунг касается обоими мечами своих лап и наносит два быстрых удара по живому стражнику.",1508,null],[10098,"2026-05-27T23:10:36",5,"/r d20+5",1508,null],[10100,"2026-05-27T23:10:54",5,"/r d20+5",1508,null],[10103,"2026-05-27T23:11:06",5,"// вторая попала?",1508,null],[10105,"2026-05-27T23:12:12",56,"//да, урон",1508,null],[10106,"2026-05-27T23:12:21",5,"/r d6",1508,null],[10109,"2026-05-27T23:12:32",5,"// яд по стражнику",1508,null],[10110,"2026-05-27T23:12:41",5,"//спас тот же, тело 12",1508,null],[10113,"2026-05-27T23:13:50",56,"/r d20+4",1508,null],[10115,"2026-05-27T23:13:55",5,"/r 2d4",1508,null],[10118,"2026-05-27T23:14:08",5,"\\\\ крит яд??",1508,null],[10119,"2026-05-27T23:14:13",56,"* этот оказался более стойким",1508,null],[10120,"2026-05-27T23:14:20",5,"// ааа",1508,null],[10121,"2026-05-27T23:14:22",5,"// точно",1508,null],[10122,"2026-05-27T23:14:23",56,"Крит спас ОТ яда",10114,null],[10124,"2026-05-27T23:14:34",5,"// ладно",1508,null],[10126,"2026-05-27T23:15:07",5,"*грунг громко квакает*",1508,null],[10127,"2026-05-27T23:15:20",44,"// так какой стражник умер ?",9610,null],[10129,"2026-05-27T23:15:36",56,"//1-ый",10127,null],[10139,"2026-05-27T23:17:39",56,"Одри продолжает писать на воздухе руны. \n— Пусть твоё кваканье станет музыкой для других\n[Вдохновение @elsio28 ]\n--------\nВ это время Второй стражник проводит две атаки по паладину, в надежде его ранить",1508,null],[10144,"2026-05-27T23:17:59",56,"/r d20+4\n/r d20+4",1508,null],[10148,"2026-05-27T23:18:18",11,"// больше Прыги и кваки",10139,null],[10149,"2026-05-27T23:18:22",56,"/r 2d8+2",1508,null],[10154,"2026-05-27T23:19:20",44,"// ммммм",10145,null],[10156,"2026-05-27T23:19:36",44,"// похуй , переживу",10154,null],[10160,"2026-05-27T23:20:03",5,"// жесть стражник с мультиатакой",1508,null],[10163,"2026-05-27T23:20:18",11,"// жесть роллы крутые",1508,null],[10164,"2026-05-27T23:20:24",5,"// я атакую в ответ реакцией",1508,null],[10165,"2026-05-27T23:20:26",56,"*два клинка впитываются в тебя, оставляя сильные раны*\nВ это время священник решает исцелить своего воина, его раны начинают заживать, а потом в паладина летит булава\n[Божественное оружие]",1508,null],[10166,"2026-05-27T23:20:36",56,"//нет, просто два клинка",10160,null],[10167,"2026-05-27T23:20:43",5,"//ааа",10166,null],[10168,"2026-05-27T23:20:44",56,"//атакуй",10164,null],[10169,"2026-05-27T23:20:47",61,"// нормально им 20 падают, а мы единички доедаем",1508,null],[10170,"2026-05-27T23:20:48",44,"// та сколкьо я урона получаю ?",10165,null],[10172,"2026-05-27T23:21:01",56,"//5 урона",10170,null],[10174,"2026-05-27T23:21:12",44,"// а от второй атаки с Критом ?",10172,null],[10175,"2026-05-27T23:21:22",5,"/r d20+5",1508,null],[10177,"2026-05-27T23:21:35",56,"/r d8",1508,null],[10180,"2026-05-27T23:21:51",56,"Ещё 3\n8 урона итого",10174,null],[10182,"2026-05-27T23:22:09",5,"/r d6",1508,null],[10183,"2026-05-27T23:22:09",44,"// а когда по мне урон попадает то мало получаю , карма называет",10178,null],[10185,"2026-05-27T23:22:18",5,"// вдохновение",1508,null],[10186,"2026-05-27T23:22:27",5,"// 13 итого",1508,null],[10187,"2026-05-27T23:22:28",56,"Промахнулся",10185,null],[10188,"2026-05-27T23:22:33",5,"//ладно",1508,null],[10189,"2026-05-27T23:23:05",56,"/r d8+3 священник лечит война\n/r d20+5 наносит удар божественным оружиес",1508,null],[10194,"2026-05-27T23:23:26",56,"/r d8+3 урон по паладину",1508,null],[10196,"2026-05-27T23:23:35",44,"// ну пока",10195,null],[10199,"2026-05-27T23:23:40",56,"//ходы окончены",1508,null],[10200,"2026-05-27T23:23:49",56,"//спас от смерти",10196,null],[10202,"2026-05-27T23:23:57",44,"/r 1d20",10200,null],[10204,"2026-05-27T23:24:16",44,"// мне копилку",10203,null],[10206,"2026-05-27T23:24:51",44,"// вы сосунки , ждите когда я встану или кто-то стабилизирует меня , или я вам все пизды",1508,null],[10207,"2026-05-27T23:25:19",5,"// а если отхилить спеллом паладина, то он сразу встанет?",1508,null],[10209,"2026-05-27T23:25:32",56,"//да",10207,null],[10212,"2026-05-27T23:26:16",61,"использую лечащее слово на дварфа",1508,null],[10213,"2026-05-27T23:26:25",56,"//кидай",1508,null],[10214,"2026-05-27T23:26:35",61,"/r d4+3",1508,null],[10217,"2026-05-27T23:27:11",44,"// да хватить , стоп я сейчас свою черту прочитаю , просто кажется я час ну фул отхилися",10215,null],[10218,"2026-05-27T23:27:30",5,"*Грунг сдерживает себя, чтобы не пнуть лежащего дварфа*",10206,null],[10220,"2026-05-27T23:28:18",61,"кидаю магический камень в диакона",1508,null],[10221,"2026-05-27T23:28:27",61,"/r d20+3",1508,null],[10226,"2026-05-27T23:29:58",61,"/r d6+3",1508,null],[10231,"2026-05-27T23:31:13",56,"// @Az095as0 твой ход",1508,null],[10234,"2026-05-27T23:31:54",44,"// @Psinablohastay я получаю 4 хп да  или 3 ? Просто у меня было 9 хп и меня отпустили -10",10215,null],[10239,"2026-05-27T23:32:41",56,"4 хп",10234,null],[10240,"2026-05-27T23:32:49",5,"// хз как отхил на тебе работает",10234,null],[10244,"2026-05-27T23:33:08",44,"// я тоже я всегда знал как умерать .",10240,null],[10250,"2026-05-27T23:34:40",44,"// можешь описать кто меня окружают сейчас ?",10231,null],[10256,"2026-05-27T23:35:56",56,"Перед тобой один стражник, священник стоит сзади, направляя на тебя оружие",1508,null],[10267,"2026-05-27T23:39:49",44,"// 7 хп хватит на победу ? Похуй потом узнаем .\n\n* Когда я встаю, вся кровь, которая была пролита из-за этого заклина , возвращается обратно (черта Невероятное восстановление).\nЯ поднимаю свое оружие с пола. Оглядываюсь назад и, увидев жреца, испытываю ярость. Я замахиваюсь своим двуручным мечом так, чтобы убить его одним ударом.",10256,null],[10268,"2026-05-27T23:39:58",44,"/r 1d20+5",10267,null],[10271,"2026-05-27T23:40:51",44,"// как не удобно когда мастера скрывают сколько КД у врагов, и каждый раз нужно ждать попал или нет",10269,null],[10272,"2026-05-27T23:41:35",5,"// можно сразу урон кидать и не применять если нет",1508,null],[10273,"2026-05-27T23:41:52",44,"/r 2d6+3",10269,null],[10275,"2026-05-27T23:42:11",44,"//",10274,null],[10277,"2026-05-27T23:42:48",44,"// не один жрец не имеет  больше 13 хп",10274,null],[10278,"2026-05-27T23:43:02",11,"// он получил 4 урона от меня ранее",1508,null],[10279,"2026-05-27T23:43:11",5,"🍊",1508,null],[10280,"2026-05-27T23:43:37",56,"//а вы думаете, откуда у него заклинание 2-го уровня?",10277,null],[10281,"2026-05-27T23:44:01",44,"// бля второй уровень, ну тогда может он и выживет",10280,null],[10283,"2026-05-27T23:44:49",56,"//он выживет",10281,null],[10284,"2026-05-27T23:45:40",5,"// 3",10281,null],[10285,"2026-05-27T23:45:50",11,"//мой ход?",1508,null],[10286,"2026-05-27T23:45:52",44,"// 17 урона , на минуточку . За ход и хочешь сказать что он выживет  . Пиздец",10283,null],[10287,"2026-05-27T23:45:57",44,"// я про заклинание",10284,null],[10288,"2026-05-27T23:46:29",56,"//да",10285,null],[10289,"2026-05-27T23:46:44",56,"//третий уровень",10287,null],[10290,"2026-05-27T23:47:36",11,"Использую погребальный звон на диаконе",1508,null],[10291,"2026-05-27T23:47:55",44,"// я про второго уровня заклинание",10289,null],[10292,"2026-05-27T23:48:20",56,"//сложность?",10290,null],[10294,"2026-05-27T23:48:36",56,"/r d20+5 спас мудрости",1508,null],[10297,"2026-05-27T23:48:45",56,"//забей",10295,null],[10299,"2026-05-27T23:49:46",5,"// я?",1508,null],[10300,"2026-05-27T23:49:49",56,"//этот весь ход?",1508,null],[10302,"2026-05-27T23:50:02",11,"// это доп действие?\nРазве я могу ещё что-то сделать?",1508,null],[10303,"2026-05-27T23:51:24",56,"//ну раз доп. Действия нет, то всë",10302,null],[10304,"2026-05-27T23:51:41",5,"Грунг передвигается ближе к паладину, чтобы доставать и стражника, и дьякона. А затем обрушивает атаки обоих мечей на дьякона.",1508,null],[10305,"2026-05-27T23:51:58",5,"/r d20+5\n/r d20+5",1508,null],[10307,"2026-05-27T23:52:15",5,"/r d6+3",1508,null],[10309,"2026-05-27T23:52:23",5,"// спас от яда?",1508,null],[10310,"2026-05-27T23:52:27",5,"// или он умер",1508,null],[10311,"2026-05-27T23:52:54",46,"//Да не умер он в конце драива",1508,null],[10312,"2026-05-27T23:53:30",56,"//умер",10308,null],[10313,"2026-05-27T23:53:34",11,"// хитрый лис везде пролезет",10311,null],[10314,"2026-05-27T23:54:27",5,"Наблюдая за падающим телом дьякона, к'Варсио громко квакает и прыгает на месте.",1508,null],[10315,"2026-05-27T23:54:29",44,"// и опять долгое описание . Блин жаба могла намазать ядом и мое оружие",1508,null],[10316,"2026-05-27T23:54:50",5,"// дварфов я мажу ядом по телу",10315,null],[10317,"2026-05-27T23:54:53",5,"// чтобы они страдали",1508,null],[10318,"2026-05-27T23:54:56",11,"// Ты жабе не нравишься",10315,null],[10319,"2026-05-27T23:55:10",5,"// конец хода",1508,null],[10320,"2026-05-27T23:55:18",44,"// у них сопротивление",10317,null],[10321,"2026-05-27T23:55:38",44,"// так что это просто крем для заговор",10320,null],[10322,"2026-05-27T23:56:26",5,"// значит придётся добавить сталь",10321,null],[10323,"2026-05-27T23:56:31",56,"/r d20",1508,null],[10325,"2026-05-27T23:56:42",56,"/r 2d8",1508,null],[10327,"2026-05-27T23:56:49",44,"// о это мне , блин  не нужно так щедро",10324,null],[10328,"2026-05-27T23:57:11",56,"Нет, не тебе, нг могу и тебе дать",10327,null],[10329,"2026-05-27T23:57:15",56,"Раз ты хочешь",1508,null],[10330,"2026-05-27T23:57:27",44,"// все равно встану как медоед",10329,null],[10331,"2026-05-27T23:57:48",56,"/r d20",1508,null],[10333,"2026-05-27T23:57:51",11,"// а затем друид тратит ещё одну ячейку на хил гнома",1508,null],[10334,"2026-05-27T23:58:00",56,"/r 4d6",1508,null],[10336,"2026-05-27T23:58:12",56,"Ох.....",1508,null],[10337,"2026-05-27T23:58:15",5,"// что кидаешь",1508,null],[10338,"2026-05-27T23:58:16",44,"// да не нужно , достойно просто стабилизировать меня , я сам стану",10333,null],[10339,"2026-05-27T23:58:25",56,"//Одри походил",10337,null],[10340,"2026-05-27T23:58:33",56,"//пзда стражнику",1508,null],[10341,"2026-05-27T23:59:07",11,"// помянем",1508,null],[10342,"2026-05-27T23:59:09",5,"//ну стражник всё равно уже проиграл",1508,null],[10345,"2026-05-28T00:05:46",56,"— Я устал от всего этого!\n\nОдри больше не ждёт. Он движется прямо на стражника — стремительно, но без единого лишнего движения, как хищник, настигающий загнанную жертву. В его глазах не осталось ни страха, ни сомнений, только холод  спокойный и неумолимый. Стражник шарахается назад, спотыкается, инстинктивно вскидывает оружие, но поздно.\n\nПар, что вечно струился из груди Одри, вдруг обращается языками пламени  ослепительно-яркими, почти белыми от жара. Огонь не разливается бесформенно, а обволакивает фигуру стражника плотным коконом. Воздух наполняется сухим, потрескивающим гулом горящих книг, запахом палёной бумаги и раскалённого металла.\n\nКогда пламя угасает, на полу остаётся лишь обугленное тело в докрасна раскалённых доспехах пальцы ещё слабо подёргиваются в посмертном спазме.\n\nОдри даже не оборачивается. Он направляется к выходу и останавливается у дверного проёма, оборачиваясь к вам через плечо:\n\n— Идём, нам пора. Ландер, наверное, заждался. Нужно поторопиться.\n\nИ он уходит — размеренным шагом, с лёгкостью, почти эльфийской походкой, словно и не было только что никакого убийства.",1508,null],[10346,"2026-05-28T00:06:37",5,"// а можно лутать врагов или тут так не принято?",1508,null],[10347,"2026-05-28T00:07:35",5,"Грунг, не получившей ни царапины, выходит вслед за ним, бросая снисходительный взгляд на дварфа",1508,null],[10348,"2026-05-28T00:07:41",11,"// щас будем драться за лут кста если можно",1508,null],[10349,"2026-05-28T00:07:57",44,"// тут все принято , но нужно задать другой вопрос , а за сколько секунд меня отпиздять мимики , крысы и высекая нежатей",10346,null],[10350,"2026-05-28T00:08:12",5,"// кстати там долго до конца, а то я уже спать хочу?",1508,null],[10351,"2026-05-28T00:08:26",44,"// вроде это уже конец",10350,null],[10352,"2026-05-28T00:08:28",56,"// я тоже",10350,null],[10353,"2026-05-28T00:08:58",44,"// спать хотите, нельзя , кто будет вести игру кроме вас?",10352,null],[10354,"2026-05-28T00:09:19",56,"//тазашо",10353,null],[10355,"2026-05-28T00:09:23",5,"// тогда давайте переходить к эпилогу или что там",10352,null],[10356,"2026-05-28T00:09:25",56,"//давайте побыстрее",1508,null],[10357,"2026-05-28T00:09:38",44,"// да , тоже согласен",10355,null],[10358,"2026-05-28T00:10:55",11,"Следую за Одри",10345,null],[10359,"2026-05-28T00:11:01",61,"Виктор подобрал еще несколько камней, пошел в след за остальными",1508,null],[10360,"2026-05-28T00:11:28",11,"//Надо же чем-то бросаться",1508,null],[10366,"2026-05-28T00:18:33",44,"// походу конец мы не узнаем .",1508,null],[10369,"2026-05-28T00:20:35",44,"// @Psinablohastay ты пишешь или нет ? Просто Я не вижу",1508,null],[10371,"2026-05-28T00:22:19",56,"Тот самый священник, что ещё недавно стоял перед вами в лучах утреннего солнца — исполненный тихой мудрости, пахнущий полевой травой и умиротворением — теперь лежит на холодной земле. Его тело представляет собой ужасное зрелище: тёмная ряса изодрана в клочья и пропитана алым, раны кровоточат, не встречая преграды, а некоторые части тела… отсутствуют вовсе, оставляя зазубренные, неестественные очертания там, где должна быть плоть. Грудь старика вздымается редко и судорожно, каждый вдох даётся с влажным, клокочущим звуком. Видно, что он доживает последние крохи отпущенной ему жизни, и пламя, которое он так долго искал, теперь теплится лишь в нём самом — крохотным, угасающим угольком.\n\nСова, его верная спутница, сидит поодаль на камне, взъерошенная, с надломленным крылом, и не сводит с хозяина круглых, полных скорбного понимания глаз.\n\nОдри ускоряет шаг. В его походке нет суетливости, но есть странная, почти механическая целеустремлённость. Он приближается к умирающему быстро, решительно, и опускается рядом на одно колено.\n\nЛандер, почувствовав его присутствие — не увидев, но учуяв знакомый запах, или услышав особый ритм шагов, или ощутив тепло, исходящее от тела, — тянется к нему дрожащей, изуродованной рукой. Пальцы его, перепачканные кровью и землёй, находят ладонь Одри. И в тот самый миг, когда их кожа соприкасается, на лице слепого старика, искажённом болью и агонией, расцветает улыбка. Слабая, почти детская, пробивающаяся сквозь муку, как первый росток сквозь выжженную землю.\n\n— Хотя бы… \nголос его, едва слышный шёпот, сорванный и прерывистый, но в нём нет ни капли горечи. \n— Хотя бы я почувствовал твоё тепло… как раньше. Это единственное… что меня радует сейчас.\n\nОн делает паузу, собираясь с силами. Кровь пузырится в уголке его губ. Сова издаёт тихий, жалобный крик.\n\n— Скажи им спасибо…\n продолжает Ландер, и вы понимаете, что он говорит о вас. \n— Тем, кто нашёл тебя. Награда у меня… \nон слабо похлопывает себя по груди, где под рясой что-то тяжело позвякивает.\n — По семьдесят пять каждому… Прошу, передай за меня… ладно?\n\nОн не ждёт ответа. Он знает, что Одри сделает это. Последний выдох, долгий и протяжный, срывается с его губ — и тело обмякает. Улыбка застывает на лице, делая его умиротворённым и почти юным, несмотря на седину. Ландер Доэ, повинующийся священник, ушёл туда, где, быть может, снова встретит своё пламя — уже навсегда.\n\nНаступает тишина. Тяжёлая, плотная, нарушаемая лишь завыванием сквозняка и далёким эхом капель.\n\nОдри смотрит на мёртвого старика. Его лицо абсолютно бесстрастно. Ни скорби, ни сожаления, ни облегчения. Только безразличие, холодное и непроницаемое, как ледяная корка на зимнем озере. Он аккуратно высвобождает свою руку из застывшей хватки Ландера и поднимается с колена, отряхивая пыль.\n\n— Прости, Ландер,\n произносит он ровным голосом, лишённым эмоций. \n\n— Ты должен был знать раньше.\n\nВ этих словах повисает невысказанная тайна, тяжёлая, как надгробная плита. Что должен был знать старик? Какую правду унёс с собой в могилу? И почему Одри, тот самый Поэт, которого Ландер искал полвека, смотрит на него сейчас с таким пугающим спокойствием?\n\n Одри запускает руку под рясу священника и извлекает оттуда увесистый кожаный мешок. Тот глухо звякает — внутри монеты, много. Он взвешивает мешок в ладони и, развернувшись, протягивает его вашему паладину.\n\n— Будь добр, раздели между своими. Ты слышал его. По семьдесят пять каждому.\n\nМешок переходит в руки паладина. Сова, хромая, перелетает на плечо Одри, и тот никак не реагирует — просто стоит и ждёт, пока вы отсчитаете свою плату, глядя куда-то сквозь вас, в темноту, из которой вы только что вышли.\n\nЗолото звенит в тишине. Мёртвый священник лежит у ваших ног, и его последняя улыбка обращена к сводам пещеры, словно там, наверху, он наконец увидел свет.",1508,null],[10372,"2026-05-28T00:22:30",56,"//ищу заготовленый",10369,null],[10374,"2026-05-28T00:22:48",44,"// ебать тут текста",10373,null],[10375,"2026-05-28T00:22:55",56,"// ну и на этом, я считаю можно заканчивать",1508,null],[10376,"2026-05-28T00:23:21",44,"// это конец ваншота, да?",10375,null],[10377,"2026-05-28T00:23:34",56,"//верно, всë",10376,null],[10378,"2026-05-28T00:23:51",5,"// спасибо за игру всем и мастеру особенно",1508,null],[10379,"2026-05-28T00:24:26",44,"// слава богу , я думал ещё два часа нужно потратить. Ладно прочитаю твой 1000 тоный текст и сделаю оценку",10377,null],[10380,"2026-05-28T00:26:50",56,"ИТОГ:\nкаждый получает:\nОпыт:\n200 за социальное взаимодействие\n400 за убийство 2-х воинов 2-го уровня и жреца 3-го уровня\nИтого: 600 опыта всем участникам\nНаграда:\n75 золотых\n+ \nЕдиноразоввй свиток доспехов мага для @elsio28",1508,null],[10381,"2026-05-28T00:27:11",56,"Ну и там отзыв, оценочку, все дела",1508,null],[10382,"2026-05-28T00:27:17",56,"Чо как, норм нет?",1508,null],[10383,"2026-05-28T00:27:25",56,"А я спать",1508,null],[10384,"2026-05-28T00:28:44",11,"// Спасибо за игру! Было весело",1508,null],[10386,"2026-05-28T00:29:11",44,"Нормально ,но вот что я и Виктор корнеплод могли его спасти ,А ты не дал .\nА так ставлю \n8/10 \nНе иза того что ты подкупил меня опытом .",10382,null],[10387,"2026-05-28T00:30:37",11,"Спокойной ночи",10383,null],[10389,"2026-05-28T00:31:29",44,"Спокойной ночи пупсик , а я пойду пропивать все деньги",10383,null],[10390,"2026-05-28T00:31:45",61,"прикольный квест, головоломка понравилась, и сюжет в целом тоже",1508,null],[10391,"2026-05-28T00:32:03",61,"спокойной, спасибо за игру!",10383,null],[10392,"2026-05-28T00:34:12",11,"Мне сравнивать не с чем, но линия повествования четкая и понятная, загадка интересная хотя мы ее решили по большей мере методом тыка😅\nВ целом было весело\nЖаль что конец скомканный вышел, согласна тут с дварфом, можно было бы попытаться что-то ещё сделать, но я понимаю что вам спать охота \nТак что 9/10 (-балл за птср для феи от кулака хд)",1508,null],[10400,"2026-05-28T07:22:44",5,"Квест понравился, было весело! (Одри жмот, что за хлам ты мне впарил? [Опустим момент, что это я выклянчивал свиток])",1508,null],[10401,"2026-05-28T07:41:48",36,"Квест охуенный!\n(Я не играла, в душе не ебу что тут было, но мне все понравилось)",1508,null],[10420,"2026-05-28T10:25:27",23,"вкратце пишите что здесь было//",1508,null],[10421,"2026-05-28T10:25:51",23,"У меня зарядка сдохла Я не смог поиграть",1508,null],[10422,"2026-05-28T10:26:15",36,"//они закончили квест",10421,null],[10423,"2026-05-28T10:26:23",36,"//короче быть не может",1508,null],[10424,"2026-05-28T10:26:32",5,"//Вот из дневника героя",1508,null],[10425,"2026-05-28T10:26:37",5,"//🏕 История приключений:\n\n1. \"Клинки, пламя и строки\" 25-27.05.26\nК'Варсио в компании ещё 4 искателей приключений отправился на поиски пропавшего поэта и обнаружил того запертым в пещере. Поэт Одрициус оказался драконом, ставшим человеком и страстно желающим освободиться от поклонявшегося ему культа Дракона. Герои разогнали культистов, а красный грунг, ведомый жаждой знаний, получил от Одри могущественный свиток заклинания \"Доспехи мага\". Кобольд по пути потерялся.",1508,null],[10426,"2026-05-28T10:26:48",23,"хз",1508,null],[10427,"2026-05-28T10:27:07",23,"мда остался В итоге без опыта пиздец весело",1508,null],[10428,"2026-05-28T10:27:40",5,":(",1508,null],[10429,"2026-05-28T10:29:13",36,"//накидай ему @Psinablohastay за присутствие",10427,null],[10430,"2026-05-28T10:29:44",56,"//да, возьми себе 300 опыта за участие, пусть и небольшое",10427,null],[10431,"2026-05-28T10:30:00",56,"//и если с тобой поделять другие, то я буду очень рад",1508,null],[10432,"2026-05-28T10:33:16",5,"Позже увидев кобольда на фестивале, грунг не стал подходить и делиться наградой. Он посчитал, что исчезнувший до начала неприятностей спутник ничего не заслужил.",1508,null],[10433,"2026-05-28T10:33:19",5,"// ничего личного",1508,null],[10436,"2026-05-28T10:36:32",36,"//не сюда",10432,null],[10440,"2026-05-28T10:45:39",5,"// сюда, тут без взаимодействий, а ответ на вопрос",10431,null],[10444,"2026-05-28T10:53:33",23,"о'кей хотя бы второй уровень",10430,null]]);
